  name: string;
  category: string;
  kgPerUnit: string;
  yieldPercentage: string;
  purchaseValue: string;
  costPerKg: string;
  status: string;
  caixasPorPalete: number;
  pesoLiquidoPorCaixa: string;
  comprimentoCaixa: string;
  larguraCaixa: string;
