import { Package, Wheat, Box, Zap, Droplet, Scale, ChefHat } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";

interface InputMaterialsSectionProps {
  insumos: any[]; // Using any temporarily until types are fixed
}

const getCategoryIcon = (category: string) => {
  switch (category) {
    case 'PESADINHA':
      return <Scale className="text-corporate mr-2" size={18} />;
    case 'MASSA':
      return <Wheat className="text-corporate mr-2" size={18} />;
    case 'EMBALAGEM':
      return <Box className="text-corporate mr-2" size={18} />;
    case 'ADITIVOS':
      return <Zap className="text-corporate mr-2" size={18} />;
    case 'LIQUIDOS':
      return <Droplet className="text-corporate mr-2" size={18} />;
    default:
      return <Package className="text-corporate mr-2" size={18} />;
  }
};

const getCategoryTitle = (category: string) => {
  switch (category) {
    case 'PESADINHA':
      return 'Pesadinha';
    case 'MASSA':
      return 'Massa';
    case 'EMBALAGEM':
      return 'Embalagem';
    case 'ADITIVOS':
      return 'Aditivos';
    case 'LIQUIDOS':
      return 'Líquidos';
    default:
      return category;
  }
};

export default function InputMaterialsSection({ insumos }: InputMaterialsSectionProps) {
  // Group insumos by category
  const groupedInsumos = insumos.reduce((acc: any, insumo: any) => {
    const category = insumo.category || 'MASSA';
    if (!acc[category]) {
      acc[category] = [];
    }
    acc[category].push(insumo);
    return acc;
  }, {} as Record<string, any[]>);

  // Calculate totals by category
  const calculateCategoryTotal = (categoryInsumos: any[]) => {
    return categoryInsumos.reduce((total, insumo) => total + parseFloat(insumo.finalCostPerKg || '0'), 0);
  };

  const totalCost = insumos.reduce((total, insumo) => total + parseFloat(insumo.finalCostPerKg || '0'), 0);

  // Define order for categories
  const categoryOrder = ['MASSA', 'PESADINHA', 'EMBALAGEM'];
  const orderedCategories = categoryOrder.filter(cat => groupedInsumos[cat]);

  return (
    <div className="space-y-8">
      {insumos.length === 0 ? (
        <Card className="mb-8 shadow-sm border border-gray-200">
          <CardContent className="p-6">
            <div className="text-center py-8 text-gray-500">
              Nenhum insumo cadastrado para este produto
            </div>
          </CardContent>
        </Card>
      ) : (
        <>
          {orderedCategories.map((category) => {
            const categoryInsumos = groupedInsumos[category];
            return (
              <Card key={category} className="mb-8 shadow-sm border border-gray-200">
                <div className="px-6 py-4 border-b border-gray-200">
                  <h3 className="text-lg font-semibold text-gray-800 flex items-center">
                    <div className="w-1 h-6 bg-corporate rounded-full mr-3"></div>
                    {getCategoryIcon(category)}
                    {getCategoryTitle(category)}
                  </h3>
                </div>

                <CardContent className="p-6">
                  <div className="overflow-x-auto">
                    <table className="w-full">
                      <thead className="bg-gray-50">
                        <tr>
                          <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Código</th>
                          <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Descrição</th>
                          <th className="px-6 py-4 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">Peso (g)</th>
                          <th className="px-6 py-4 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">Peso %</th>
                          <th className="px-6 py-4 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">Rend %</th>
                          <th className="px-6 py-4 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Valor/Kg</th>
                        </tr>
                      </thead>
                      <tbody className="bg-white divide-y divide-gray-200">
                        {categoryInsumos.map((insumo: any) => (
                          <tr 
                            key={insumo.id}
                            className={`hover:bg-gray-50 transition-colors ${
                              parseFloat(insumo.yieldPercentage || '100') < 70 ? 'border-l-4 border-red-200' : ''
                            }`}
                          >
                            <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-corporate">{insumo.code}</td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">{insumo.name}</td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 text-center">
                              {insumo.pesoUsado ? `${insumo.pesoUsado}kg` : '-'}
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-center text-blue-600">
                              {insumo.percentualPeso ? `${insumo.percentualPeso}%` : '-'}
                            </td>
                            <td className={`px-6 py-4 whitespace-nowrap text-sm font-medium text-center ${
                              parseFloat(insumo.rendimentoPercent || '100') < 70 ? 'text-red-600' : 'text-gray-900'
                            }`}>
                              {insumo.rendimentoPercent ? `${insumo.rendimentoPercent}%` : '100%'}
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm font-semibold text-gray-900 text-right">
                              R$ {insumo.purchasePrice || '0,00'}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </CardContent>
              </Card>
            );
          })}

        </>
      )}
    </div>
  );
}

