import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { AlertTriangle, TrendingUp, TrendingDown, X, CheckCircle } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/lib/auth-context";
import { apiRequest } from "@/lib/queryClient";

export default function InsumoVariationsAlert() {
  const { user, permissions } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [dismissedVariations, setDismissedVariations] = useState<number[]>([]);

  // Don't show alerts for consultation users
  if (user?.userType === 'consulta' || !permissions?.canEdit) {
    return null;
  }

  const { data: variations = [], isLoading } = useQuery({
    queryKey: ["/api/insumo-variations"],
    refetchInterval: 30000, // Check every 30 seconds
  });

  const acknowledgeMutation = useMutation({
    mutationFn: async (variationId: number) => {
      const response = await apiRequest("POST", `/api/insumo-variations/${variationId}/acknowledge`);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/insumo-variations"] });
      toast({
        title: "Variação reconhecida",
        description: "A variação foi marcada como reconhecida.",
      });
    },
    onError: () => {
      toast({
        title: "Erro",
        description: "Erro ao reconhecer variação.",
        variant: "destructive",
      });
    },
  });

  const handleDismiss = (variationId: number) => {
    setDismissedVariations(prev => [...prev, variationId]);
  };

  const handleAcknowledge = (variationId: number) => {
    acknowledgeMutation.mutate(variationId);
  };

  // Filter out dismissed variations
  const activeVariations = variations.filter(v => !dismissedVariations.includes(v.id));

  if (isLoading || activeVariations.length === 0) {
    return null;
  }

  return (
    <div className="space-y-4">
      {activeVariations.map((variation) => {
        const isIncrease = variation.percentualVariacao > 0;
        const severity = Math.abs(variation.percentualVariacao) > 10 ? "high" : 
                        Math.abs(variation.percentualVariacao) > 5 ? "medium" : "low";

        return (
          <Alert key={variation.id} className={`border-l-4 ${
            severity === "high" ? "border-l-red-500 bg-red-50" :
            severity === "medium" ? "border-l-yellow-500 bg-yellow-50" :
            "border-l-blue-500 bg-blue-50"
          }`}>
            <div className="flex items-start justify-between">
              <div className="flex items-start gap-3">
                <AlertTriangle className={`h-5 w-5 mt-0.5 ${
                  severity === "high" ? "text-red-600" :
                  severity === "medium" ? "text-yellow-600" :
                  "text-blue-600"
                }`} />
                <div className="flex-1">
                  <AlertDescription>
                    <div className="font-medium text-gray-900 mb-2">
                      Variação de Custo Detectada: {variation.insumoName} ({variation.insumoCode})
                    </div>
                    <div className="space-y-2">
                      <div className="flex items-center gap-4 text-sm">
                        <div className="flex items-center gap-2">
                          {isIncrease ? (
                            <TrendingUp className="h-4 w-4 text-red-600" />
                          ) : (
                            <TrendingDown className="h-4 w-4 text-green-600" />
                          )}
                          <span className={`font-medium ${
                            isIncrease ? "text-red-600" : "text-green-600"
                          }`}>
                            {isIncrease ? "+" : ""}{variation.percentualVariacao.toFixed(1)}%
                          </span>
                        </div>
                        <div className="text-gray-600">
                          Impacto no preço final: {variation.impactoNoPreco.toFixed(1)}%
                        </div>
                      </div>

                      <div className="flex items-center gap-4 text-sm text-gray-600">
                        <span>
                          R$ {parseFloat(variation.valorAnterior).toFixed(2)} → 
                          R$ {parseFloat(variation.valorNovo).toFixed(2)}
                        </span>
                        <Badge variant={
                          severity === "high" ? "destructive" :
                          severity === "medium" ? "secondary" : "default"
                        }>
                          {severity === "high" ? "Alto Impacto" :
                           severity === "medium" ? "Médio Impacto" : "Baixo Impacto"}
                        </Badge>
                      </div>
                    </div>
                  </AlertDescription>
                </div>
              </div>

              <div className="flex items-center gap-2 ml-4">
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => handleAcknowledge(variation.id)}
                  disabled={acknowledgeMutation.isPending}
                  className="text-green-600 border-green-300 hover:bg-green-50"
                >
                  <CheckCircle className="h-4 w-4 mr-1" />
                  Reconhecer
                </Button>
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => handleDismiss(variation.id)}
                  className="text-gray-500 hover:text-gray-700"
                >
                  <X className="h-4 w-4" />
                </Button>
              </div>
            </div>
          </Alert>
        );
      })}
    </div>
  );
}

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { 
  TrendingUp, 
  TrendingDown, 
  AlertTriangle, 
  Package, 
  Calculator,
  DollarSign,
  Target
} from "lucide-react";
import { apiRequest } from "@/lib/queryClient";
import { useAuth } from "@/lib/auth-context";

interface InsumoVariation {
  id: number;
  insumoId: number;
  insumoCode: string;
  insumoName: string;
  valorAnterior: number;
  valorNovo: number;
  percentualVariacao: number;
  impactoNoPreco: number;
  affectedProducts: Array<{
    id: number;
    code: string;
    name: string;
    currentPrice: number;
    newPrice: number;
  }>;
  createdAt: string;
  acknowledged: boolean;
}

interface DecisionForm {
  decision: 'maintain_margin' | 'maintain_price';
  newMargin?: number;
  newPrice?: number;
}

export default function InsumoVariationsDashboard() {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const [selectedVariation, setSelectedVariation] = useState<InsumoVariation | null>(null);
  const [decisionForm, setDecisionForm] = useState<DecisionForm>({ decision: 'maintain_margin' });

  const { data: variations = [], isLoading } = useQuery({
    queryKey: ["/api/insumo-variations"],
    enabled: user?.userType !== 'consulta'
  });

  const acknowledgeMutation = useMutation({
    mutationFn: async ({ variationId, decision }: { variationId: number, decision: DecisionForm }) => {
      const response = await apiRequest("POST", `/api/insumo-variations/${variationId}/acknowledge`, {
        body: JSON.stringify({
          userId: user?.id,
          decision: decision.decision,
          newMargin: decision.newMargin,
          newPrice: decision.newPrice
        })
      });
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/insumo-variations"] });
      setSelectedVariation(null);
      setDecisionForm({ decision: 'maintain_margin' });
    }
  });

  const unacknowledgedVariations = variations.filter((v: InsumoVariation) => !v.acknowledged);

  if (user?.userType === 'consulta' || unacknowledgedVariations.length === 0) {
    return null;
  }

  const handleDecision = () => {
    if (selectedVariation) {
      acknowledgeMutation.mutate({
        variationId: selectedVariation.id,
        decision: decisionForm
      });
    }
  };

  return (
    <div className="mb-8">
      <Card className="border-orange-200 bg-gradient-to-r from-orange-50 to-yellow-50">
        <CardHeader>
          <div className="flex items-center gap-2">
            <AlertTriangle className="h-5 w-5 text-orange-600" />
            <CardTitle className="text-orange-800">
              Variações de Insumos Detectadas
            </CardTitle>
            <Badge variant="destructive">
              {unacknowledgedVariations.length} {unacknowledgedVariations.length === 1 ? 'variação' : 'variações'}
            </Badge>
          </div>
        </CardHeader>
        <CardContent>
          <p className="text-orange-700 mb-4">
            Foram detectadas alterações nos custos dos insumos. Revise e tome decisões manuais sobre o impacto nos preços.
          </p>

          <div className="space-y-3">
            {unacknowledgedVariations.map((variation: InsumoVariation) => (
              <div key={variation.id} className="bg-white rounded-lg p-4 border border-orange-100">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="flex items-center gap-2">
                      {variation.percentualVariacao > 0 ? (
                        <TrendingUp className="h-4 w-4 text-red-500" />
                      ) : (
                        <TrendingDown className="h-4 w-4 text-green-500" />
                      )}
                      <div>
                        <span className="font-medium text-gray-900">
                          {variation.insumoCode} - {variation.insumoName}
                        </span>
                        <div className="text-sm text-gray-600">
                          Variação: <span className={`font-medium ${variation.percentualVariacao > 0 ? 'text-red-600' : 'text-green-600'}`}>
                            {variation.percentualVariacao > 0 ? '+' : ''}{variation.percentualVariacao.toFixed(2)}%
                          </span>
                          {' '}(R$ {variation.valorAnterior.toFixed(4)} → R$ {variation.valorNovo.toFixed(4)})
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="flex items-center gap-3">
                    <div className="text-right">
                      <div className="text-sm text-gray-600">Produtos Afetados:</div>
                      <div className="font-medium">{variation.affectedProducts.length}</div>
                    </div>

                    <Dialog>
                      <DialogTrigger asChild>
                        <Button 
                          variant="outline" 
                          size="sm"
                          onClick={() => setSelectedVariation(variation)}
                        >
                          <Calculator className="h-4 w-4 mr-1" />
                          Decidir
                        </Button>
                      </DialogTrigger>
                      <DialogContent className="max-w-2xl">
                        <DialogHeader>
                          <DialogTitle>
                            Aba de Decisão {variation.insumoCode}
                          </DialogTitle>
                        </DialogHeader>

                        <div className="space-y-6">
                          {/* Variation Summary */}
                          <div className="bg-gray-50 rounded-lg p-4">
                            <h4 className="font-medium mb-2">Resumo da Variação</h4>
                            <div className="grid grid-cols-2 gap-4 text-sm">
                              <div>
                                <span className="text-gray-600">Insumo:</span>
                                <div className="font-medium">{variation.insumoCode} - {variation.insumoName}</div>
                              </div>
                              <div>
                                <span className="text-gray-600">Variação:</span>
                                <div className={`font-medium ${variation.percentualVariacao > 0 ? 'text-red-600' : 'text-green-600'}`}>
                                  {variation.percentualVariacao > 0 ? '+' : ''}{variation.percentualVariacao.toFixed(2)}%
                                </div>
                              </div>
                              <div>
                                <span className="text-gray-600">Valor Anterior:</span>
                                <div className="font-medium">R$ {variation.valorAnterior.toFixed(4)}</div>
                              </div>
                              <div>
                                <span className="text-gray-600">Valor Novo:</span>
                                <div className="font-medium">R$ {variation.valorNovo.toFixed(4)}</div>
                              </div>
                            </div>
                          </div>

                          {/* Affected Products */}
                          <div>
                            <h4 className="font-medium mb-3 flex items-center gap-2">
                              <Package className="h-4 w-4" />
                              Produtos Afetados ({variation.affectedProducts.length})
                            </h4>
                            <div className="max-h-40 overflow-y-auto space-y-2">
                              {variation.affectedProducts.map((product) => (
                                <div key={product.id} className="flex items-center justify-between p-2 bg-gray-50 rounded">
                                  <div>
                                    <span className="font-medium">{product.code}</span>
                                    <span className="text-gray-600 ml-2">{product.name}</span>
                                  </div>
                                  <div className="text-sm">
                                    <span className="text-gray-600">R$ {product.currentPrice.toFixed(2)} → </span>
                                    <span className="font-medium">R$ {product.newPrice.toFixed(2)}</span>
                                  </div>
                                </div>
                              ))}
                            </div>
                          </div>

                          {/* Decision Options */}
                          <div>
                            <h4 className="font-medium mb-3">Opções de Decisão</h4>
                            <div className="space-y-4">
                              <div className="flex items-center space-x-2">
                                <input
                                  type="radio"
                                  id="maintain_margin"
                                  name="decision"
                                  value="maintain_margin"
                                  checked={decisionForm.decision === 'maintain_margin'}
                                  onChange={(e) => setDecisionForm({ ...decisionForm, decision: e.target.value as any })}
                                />
                                <label htmlFor="maintain_margin" className="flex items-center gap-2">
                                  <Target className="h-4 w-4 text-blue-600" />
                                  <span className="font-medium">Manter a margem líquida e aumentar o preço final</span>
                                </label>
                              </div>

                              <div className="flex items-center space-x-2">
                                <input
                                  type="radio"
                                  id="maintain_price"
                                  name="decision"
                                  value="maintain_price"
                                  checked={decisionForm.decision === 'maintain_price'}
                                  onChange={(e) => setDecisionForm({ ...decisionForm, decision: e.target.value as any })}
                                />
                                <label htmlFor="maintain_price" className="flex items-center gap-2">
                                  <DollarSign className="h-4 w-4 text-green-600" />
                                  <span className="font-medium">Diminuir a margem líquida e manter o preço</span>
                                </label>
                              </div>
                            </div>

                            {decisionForm.decision === 'maintain_price' && (
                              <div className="mt-4 p-3 bg-yellow-50 border border-yellow-200 rounded-lg">
                                <Label htmlFor="newMargin" className="text-sm font-medium">
                                  Nova Margem (%)
                                </Label>
                                <Input
                                  id="newMargin"
                                  type="number"
                                  step="0.1"
                                  placeholder="Ex: 15.5"
                                  value={decisionForm.newMargin || ''}
                                  onChange={(e) => setDecisionForm({ 
                                    ...decisionForm, 
                                    newMargin: parseFloat(e.target.value) || undefined 
                                  })}
                                  className="mt-1"
                                />
                              </div>
                            )}

                            {decisionForm.decision === 'maintain_margin' && (
                              <div className="mt-4 p-3 bg-blue-50 border border-blue-200 rounded-lg">
                                <Label htmlFor="newPrice" className="text-sm font-medium">
                                  Novo Preço (R$)
                                </Label>
                                <Input
                                  id="newPrice"
                                  type="number"
                                  step="0.01"
                                  placeholder="Ex: 12.50"
                                  value={decisionForm.newPrice || ''}
                                  onChange={(e) => setDecisionForm({ 
                                    ...decisionForm, 
                                    newPrice: parseFloat(e.target.value) || undefined 
                                  })}
                                  className="mt-1"
                                />
                              </div>
                            )}
                          </div>

                          {/* Action Buttons */}
                          <div className="flex justify-end gap-3">
                            <Button variant="outline" onClick={() => setSelectedVariation(null)}>
                              Cancelar
                            </Button>
                            <Button 
                              onClick={handleDecision}
                              disabled={acknowledgeMutation.isPending}
                            >
                              {acknowledgeMutation.isPending ? 'Processando...' : 'Confirmar Decisão'}
                            </Button>
                          </div>
                        </div>
                      </DialogContent>
                    </Dialog>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

client/src/components/logistica-avancada.content:
import { useState, useEffect } from "react";
import {
  Card, CardContent, CardHeader, CardTitle
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue
} from "@/components/ui/select";
import { Truck, Save, X } from "lucide-react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";

interface ModalidadeTransporte {
  id: number;
  nome: string;
  cubagem: string;
  custoBasePorKm?: string;
  isActive: boolean;
}

interface NovaModalidade {
  nome: string;
  cubagem: string;
  custoBasePorKm: string;
}

export default function LogisticaAvancada() {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [showNovaModalidade, setShowNovaModalidade] = useState(false);
  const [novaModalidade, setNovaModalidade] = useState<NovaModalidade>({
    nome: "",
    cubagem: "",
    custoBasePorKm: ""
  });

  const { data: modalidades = [] } = useQuery({
    queryKey: ["modalidades-transporte"],
    queryFn: async () => {
      const res = await apiRequest("GET", "/api/modalidades-transporte");
      return res.json() as Promise<ModalidadeTransporte[]>;
    }
  });

  const criarModalidadeMutation = useMutation({
    mutationFn: async (modalidade: NovaModalidade) => {
      const res = await apiRequest("POST", "/api/modalidades-transporte", modalidade);
      return res.json();
    },
    onSuccess: () => {
      toast({ title: "Modalidade criada com sucesso!" });
      queryClient.invalidateQueries({ queryKey: ["modalidades-transporte"] });
      setNovaModalidade({ nome: "", cubagem: "", custoBasePorKm: "" });
      // ATENÇÃO: não fecha o formulário!
    },
    onError: () => {
      toast({ title: "Erro", description: "Erro ao criar modalidade", variant: "destructive" });
    }
  });

  return (
    <Card className="mb-6">
      <CardHeader>
        <CardTitle className="flex justify-between items-center">
          <span className="flex items-center gap-2">
            <Truck className="h-5 w-5" /> Logística e Transporte
          </span>
          {!showNovaModalidade && (
            <Button size="sm" variant="outline" onClick={() => setShowNovaModalidade(true)}>
              Criar Modalidade
            </Button>
          )}
        </CardTitle>
      </CardHeader>

      <CardContent className="space-y-6">
        {/* Formulário nova modalidade */}
        {showNovaModalidade && (
          <div className="border rounded-lg p-4 bg-gray-50 relative">
            <button
              className="absolute top-2 right-2 text-gray-500 hover:text-red-500"
              onClick={() => setShowNovaModalidade(false)}
            >
              <X className="h-4 w-4" />
            </button>
            <h4 className="font-medium mb-4">Nova Modalidade</h4>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
              <div>
                <Label>Nome</Label>
                <Input
                  value={novaModalidade.nome}
                  onChange={(e) =>
                    setNovaModalidade(prev => ({ ...prev, nome: e.target.value }))
                  }
                />
              </div>
              <div>
                <Label>Cubagem (m³)</Label>
                <Input
                  type="number"
                  value={novaModalidade.cubagem}
                  onChange={(e) =>
                    setNovaModalidade(prev => ({ ...prev, cubagem: e.target.value }))
                  }
                />
              </div>
              <div>
                <Label>Custo Base por Km (R$)</Label>
                <Input
                  type="number"
                  step="0.01"
                  value={novaModalidade.custoBasePorKm}
                  onChange={(e) =>
                    setNovaModalidade(prev => ({ ...prev, custoBasePorKm: e.target.value }))
                  }
                />
              </div>
              <div className="flex items-end">
                <Button
                  onClick={() => criarModalidadeMutation.mutate(novaModalidade)}
                  disabled={
                    !novaModalidade.nome ||
                    !novaModalidade.cubagem ||
                    !novaModalidade.custoBasePorKm
                  }
                  className="w-full"
                >
                  <Save className="h-4 w-4 mr-2" /> Salvar
                </Button>
              </div>
            </div>
          </div>
        )}

        {/* Lista de modalidades existentes */}
        <div>
          <h4 className="font-medium mb-2">Modalidades Criadas</h4>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
            {modalidades.filter(m => m.isActive).map(modalidade => (
              <div
                key={modalidade.id}
                className="p-3 border rounded-md flex justify-between items-center"
              >
                <div>
                  <div className="font-medium">{modalidade.nome}</div>
                  <div className="text-sm text-gray-600">
                    {modalidade.cubagem} m³ | R$ {modalidade.custoBasePorKm}/km
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

client/src/components/logistica-melhorad.content:
import { useState, useEffect } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Truck, Package, Plus, Calculator, Edit2, Trash2 } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

interface LogisticaMelhoradaProps {
  productId: string;
  userCanEdit?: boolean;
}

interface Modalidade {
  id: number;
  nome: string;
  valorFixo: number;
  tipo: string;
  cubagemMaxima?: number;
  capacidadePaletes?: number;
  isActive: boolean;
}

interface NovaModalidade {
  nome: string;
  valorFixo: string;
  tipo: string;
  cubagemMaxima: string;
  capacidadePaletes: string;
}

export default function LogisticaMelhorada({ productId, userCanEdit = false }: LogisticaMelhoradaProps) {
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const [showNewModalidadeForm, setShowNewModalidadeForm] = useState(false);
  const [editingModalidade, setEditingModalidade] = useState<number | null>(null);
  const [selectedModalidade, setSelectedModalidade] = useState<string>("");
  const [quantidadeTransportada, setQuantidadeTransportada] = useState<string>("");
  const [resultadoCalculo, setResultadoCalculo] = useState<any>(null);

  const [novaModalidade, setNovaModalidade] = useState<NovaModalidade>({
    nome: "",
    valorFixo: "",
    tipo: "terrestre",
    cubagemMaxima: "",
    capacidadePaletes: "",
  });

  const { data: modalidades = [], isLoading } = useQuery({
    queryKey: ['/api/modalidades-transporte'],
    queryFn: async () => {
      const response = await fetch('/api/modalidades-transporte');
      if (!response.ok) throw new Error('Failed to fetch modalidades');
      return response.json();
    },
  });

  const { data: calculosPrevios = [] } = useQuery({
    queryKey: [`/api/products/${productId}/logistics-calculations`],
    queryFn: async () => {
      const response = await fetch(`/api/products/${productId}/logistics-calculations`);
      if (!response.ok) return [];
      return response.json();
    },
  });

  const criarModalidadeMutation = useMutation({
    mutationFn: async (modalidade: NovaModalidade) => {
      const response = await fetch('/api/modalidades-transporte', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          nome: modalidade.nome,
          valorFixo: parseFloat(modalidade.valorFixo),
          tipo: modalidade.tipo,
          cubagemMaxima: parseFloat(modalidade.cubagemMaxima) || undefined,
          capacidadePaletes: parseInt(modalidade.capacidadePaletes) || undefined,
        }),
      });
      if (!response.ok) throw new Error('Failed to create modalidade');
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/modalidades-transporte'] });
      toast({
        title: "Modalidade criada",
        description: "Nova modalidade de transporte criada com sucesso.",
      });
      setShowNewModalidadeForm(false);
      setNovaModalidade({
        nome: "",
        valorFixo: "",
        tipo: "terrestre",
        cubagemMaxima: "",
        capacidadePaletes: "",
      });
    },
    onError: () => {
      toast({
        title: "Erro",
        description: "Não foi possível criar a modalidade.",
        variant: "destructive",
      });
    },
  });

  const calcularLogisticaMutation = useMutation({
    mutationFn: async () => {
      const response = await fetch('/api/logistics/calculate', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          productId: parseInt(productId),
          modalidadeId: parseInt(selectedModalidade),
          quantidadeTransportada: parseFloat(quantidadeTransportada),
          userId: 1,
        }),
      });
      if (!response.ok) throw new Error('Failed to calculate logistics');
      return response.json();
    },
    onSuccess: (data) => {
      setResultadoCalculo(data);
      queryClient.invalidateQueries({ queryKey: [`/api/products/${productId}/logistics-calculations`] });
      toast({
        title: "Cálculo realizado",
        description: "Cálculo de logística realizado com sucesso.",
      });
    },
    onError: () => {
      toast({
        title: "Erro",
        description: "Não foi possível realizar o cálculo.",
        variant: "destructive",
      });
    },
  });

  const inicializarModalidadesPadrao = useMutation({
    mutationFn: async () => {
      const modalidadesPadrao = [
        {
          nome: "Fiorino",
          valorFixo: 250.00,
          tipo: "terrestre",
          cubagemMaxima: 2.8,
          capacidadePaletes: 2,
          isActive: true
        },
        {
          nome: "Caminhão 3/4",
          valorFixo: 450.00,
          tipo: "terrestre",
          cubagemMaxima: 15.0,
          capacidadePaletes: 8,
          isActive: true
        },
        {
          nome: "Carreta",
          valorFixo: 850.00,
          tipo: "terrestre",
          cubagemMaxima: 90.0,
          capacidadePaletes: 33,
          isActive: true
        }
      ];

      const response = await fetch('/api/modalidades-transporte/padrao', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ modalidades: modalidadesPadrao }),
      });
      if (!response.ok) throw new Error('Failed to initialize modalidades');
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/modalidades-transporte'] });
      toast({
        title: "Modalidades inicializadas",
        description: "Modalidades padrão foram criadas com sucesso.",
      });
    },
  });

  useEffect(() => {
    if (modalidades.length === 0 && !isLoading) {
      inicializarModalidadesPadrao.mutate();
    }
  }, [modalidades.length, isLoading]);

  const handleCalcular = () => {
    if (!selectedModalidade || !quantidadeTransportada) {
      toast({
        title: "Erro",
        description: "Selecione uma modalidade e informe a quantidade.",
        variant: "destructive",
      });
      return;
    }
    calcularLogisticaMutation.mutate();
  };

  const handleCriarModalidade = () => {
    if (!novaModalidade.nome || !novaModalidade.valorFixo) {
      toast({
        title: "Erro",
        description: "Preencha todos os campos obrigatórios.",
        variant: "destructive",
      });
      return;
    }
    criarModalidadeMutation.mutate(novaModalidade);
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Truck className="h-5 w-5" />
          Logística e Transporte Avançada
        </CardTitle>
        <CardDescription>
          Gerencie modalidades de transporte e calcule custos logísticos
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        {/* Modalidades Existentes */}
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-semibold">Modalidades de Transporte</h3>
            {userCanEdit && (
              <Button
                onClick={() => setShowNewModalidadeForm(!showNewModalidadeForm)}
                size="sm"
                variant="outline"
              >
                <Plus className="h-4 w-4 mr-2" />
                Nova Modalidade
              </Button>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {modalidades.map((modalidade: Modalidade) => (
              <Card key={modalidade.id} className="p-4">
                <div className="flex items-center justify-between mb-2">
                  <h4 className="font-medium">{modalidade.nome}</h4>
                  <Badge variant={modalidade.isActive ? "default" : "secondary"}>
                    {modalidade.isActive ? "Ativo" : "Inativo"}
                  </Badge>
                </div>
                <div className="space-y-1 text-sm text-gray-600">
                  <div>Valor: R$ {modalidade.valorFixo.toFixed(2)}</div>
                  <div>Tipo: {modalidade.tipo}</div>
                  {modalidade.cubagemMaxima && (
                    <div>Cubagem: {modalidade.cubagemMaxima}m³</div>
                  )}
                  {modalidade.capacidadePaletes && (
                    <div>Paletes: {modalidade.capacidadePaletes}</div>
                  )}
                </div>
              </Card>
            ))}
          </div>
        </div>

        {/* Formulário Nova Modalidade */}
        {showNewModalidadeForm && userCanEdit && (
          <div className="space-y-4 p-4 border rounded-lg bg-gray-50">
            <h3 className="text-lg font-semibold">Nova Modalidade</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="nome">Nome *</Label>
                <Input
                  id="nome"
                  value={novaModalidade.nome}
                  onChange={(e) => setNovaModalidade(prev => ({ ...prev, nome: e.target.value }))}
                  placeholder="Ex: Fiorino, Caminhão"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="valorFixo">Valor Fixo (R$) *</Label>
                <Input
                  id="valorFixo"
                  type="number"
                  step="0.01"
                  value={novaModalidade.valorFixo}
                  onChange={(e) => setNovaModalidade(prev => ({ ...prev, valorFixo: e.target.value }))}
                  placeholder="250.00"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="tipo">Tipo</Label>
                <Select
                  value={novaModalidade.tipo}
                  onValueChange={(value) => setNovaModalidade(prev => ({ ...prev, tipo: value }))}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="terrestre">Terrestre</SelectItem>
                    <SelectItem value="aereo">Aéreo</SelectItem>
                    <SelectItem value="maritimo">Marítimo</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="cubagem">Cubagem Máxima (m³)</Label>
                <Input
                  id="cubagem"
                  type="number"
                  step="0.1"
                  value={novaModalidade.cubagemMaxima}
                  onChange={(e) => setNovaModalidade(prev => ({ ...prev, cubagemMaxima: e.target.value }))}
                  placeholder="15.0"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="paletes">Capacidade de Paletes</Label>
                <Input
                  id="paletes"
                  type="number"
                  value={novaModalidade.capacidadePaletes}
                  onChange={(e) => setNovaModalidade(prev => ({ ...prev, capacidadePaletes: e.target.value }))}
                  placeholder="8"
                />
              </div>
            </div>
            <div className="flex gap-2">
              <Button
                onClick={handleCriarModalidade}
                disabled={criarModalidadeMutation.isPending}
              >
                <Plus className="h-4 w-4 mr-2" />
                Criar Modalidade
              </Button>
              <Button
                variant="outline"
                onClick={() => setShowNewModalidadeForm(false)}
              >
                Cancelar
              </Button>
            </div>
          </div>
        )}

        <Separator />

        {/* Calculadora de Logística */}
        <div className="space-y-4">
          <h3 className="text-lg font-semibold">Calculadora de Logística</h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label htmlFor="modalidade">Modalidade de Transporte</Label>
              <Select value={selectedModalidade} onValueChange={setSelectedModalidade}>
                <SelectTrigger>
                  <SelectValue placeholder="Selecione uma modalidade" />
                </SelectTrigger>
                <SelectContent>
                  {modalidades
                    .filter((m: Modalidade) => m.isActive)
                    .map((modalidade: Modalidade) => (
                      <SelectItem key={modalidade.id} value={modalidade.id.toString()}>
                        {modalidade.nome} - R$ {modalidade.valorFixo.toFixed(2)}
                      </SelectItem>
                    ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="quantidade">Quantidade a Transportar (kg)</Label>
              <Input
                id="quantidade"
                type="number"
                step="0.1"
                value={quantidadeTransportada}
                onChange={(e) => setQuantidadeTransportada(e.target.value)}
                placeholder="1000"
              />
            </div>
            <div className="flex items-end">
              <Button
                onClick={handleCalcular}
                disabled={calcularLogisticaMutation.isPending}
                className="w-full"
              >
                <Calculator className="h-4 w-4 mr-2" />
                Calcular
              </Button>
            </div>
          </div>
        </div>

        {/* Resultado do Cálculo */}
        {resultadoCalculo && (
          <div className="space-y-4 p-4 border rounded-lg bg-blue-50">
            <h3 className="text-lg font-semibold">Resultado do Cálculo</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <div className="flex justify-between">
                  <span>Cubagem por Caixa:</span>
                  <span>{resultadoCalculo.cubagemPorCaixa?.toFixed(4)} m³</span>
                </div>
                <div className="flex justify-between">
                  <span>Caixas por Veículo:</span>
                  <span>{resultadoCalculo.caixasPorVeiculo}</span>
                </div>
                <div className="flex justify-between">
                  <span>Peso Total por Veículo:</span>
                  <span>{resultadoCalculo.pesoTotalPorVeiculo} kg</span>
                </div>
              </div>
              <div className="space-y-2">
                <div className="flex justify-between">
                  <span>Número de Viagens:</span>
                  <span>{resultadoCalculo.numeroViagens}</span>
                </div>
                <div className="flex justify-between">
                  <span>Custo por Kg:</span>
                  <span>R$ {resultadoCalculo.custoPorKg?.toFixed(4)}</span>
                </div>
                <div className="flex justify-between font-semibold">
                  <span>Custo Total Estimado:</span>
                  <span>R$ {resultadoCalculo.custoTotalEstimado?.toFixed(2)}</span>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Cálculos Anteriores */}
        {calculosPrevios.length > 0 && (
          <div className="space-y-4">
            <Separator />
            <h3 className="text-lg font-semibold">Cálculos Anteriores</h3>
            <div className="space-y-2">
              {calculosPrevios.slice(0, 5).map((calculo: any) => (
                <div key={calculo.id} className="p-3 border rounded-lg text-sm">
                  <div className="flex justify-between items-center">
                    <span>
                      {calculo.quantidadeTransportada}kg - {calculo.numeroViagens} viagens
                    </span>
                    <Badge variant="outline">
                      R$ {calculo.custoTotalEstimado?.toFixed(2)}
                    </Badge>
                  </div>
                  <div className="text-xs text-gray-500 mt-1">
                    {new Date(calculo.createdAt).toLocaleDateString()} - 
                    R$ {calculo.custoPorKg?.toFixed(4)}/kg
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

