import { Truck, Car } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { useQuery } from "@tanstack/react-query";
import type { LogisticaTransporte } from "@/lib/types";

interface LogisticsSectionProps {
  logistics?: LogisticaTransporte;
  productId: string;
}

interface Modalidade {
  id: number;
  nome: string;
  valorFixo: number;
  tipo: string;
  cubagemMaxima?: number;
  capacidadePaletes?: number;
}

export default function LogisticsSection({ logistics, productId }: LogisticsSectionProps) {
  // Buscar modalidades de transporte da API
  const { data: modalidades = [] } = useQuery<Modalidade[]>({
    queryKey: ["/api/modalidades-transporte"],
    queryFn: async () => {
      const response = await fetch("/api/modalidades-transporte");
      if (!response.ok) throw new Error("Failed to fetch modalidades");
      return response.json();
    },
  });

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat("pt-BR", {
      style: "currency",
      currency: "BRL",
    }).format(value);
  };

  return (
    <Card className="mb-8 shadow-sm border border-gray-200">
      <div className="px-6 py-4 border-b border-gray-200">
        <h3 className="text-lg font-semibold text-gray-800 flex items-center">
          <div className="w-1 h-6 bg-corporate rounded-full mr-3"></div>
          <Truck className="text-corporate mr-2" size={18} />
          Modalidades de Transporte
          <Badge
            variant="outline"
            className="ml-2 text-xs bg-blue-100 text-blue-800 border-blue-200"
          >
            Valores padrão para até 50km
          </Badge>
        </h3>
      </div>

      <CardContent className="p-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {modalidades.map((modalidade) => (
            <div key={modalidade.id} className="space-y-3">
              <h4 className="font-medium text-gray-700 flex items-center">
                {modalidade.nome.toLowerCase().includes('fiorino') ? (
                  <Car className="text-corporate mr-2 text-sm" size={16} />
                ) : (
                  <Truck className="text-corporate mr-2 text-sm" size={16} />
                )}
                {modalidade.nome}
              </h4>
              <div className="bg-gray-50 p-3 rounded-lg">
                <div className="text-sm text-gray-600">
                  {modalidade.tipo === 'pequeno' && 'Até 2,5m³'}
                  {modalidade.tipo === 'medio' && 'Até 8m³'}
                  {modalidade.tipo === 'grande' && 'Até 25m³'}
                  {modalidade.cubagemMaxima && `Até ${modalidade.cubagemMaxima}m³`}
                  {modalidade.capacidadePaletes && `${modalidade.capacidadePaletes} paletes`}
                </div>
                <div className="font-semibold text-gray-900">
                  {formatCurrency(modalidade.valorFixo)}
                </div>
              </div>
            </div>
          ))}
        </div>
      </CardContent>
    </Card>
  );
}

