import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Separator } from "@/components/ui/separator";
import { AlertTriangle, Check, X, Clock, Eye, TrendingUp, TrendingDown, Calculator, Percent, DollarSign } from "lucide-react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { formatDistanceToNow } from "date-fns";
import { ptBR } from "date-fns/locale";

interface PendenciaRepasse {
  id: number;
  insumoId: number;
  productId: number;
  insumoNome: string;
  productNome: string;
  valorAnterior: string;
  valorNovo: string;
  status: "aguardando" | "aprovado" | "rejeitado";
  userId: number;
  userName: string;
  createdAt: string;
  approvedBy?: number;
  approvedAt?: string;
  impactoPercentual?: number;
  pesoComposicao?: number;
  margemSugerida?: number;
  custoFinalAnterior?: number;
  custoFinalNovo?: number;
}

interface PendenciasRepasseProps {
  productId?: number;
  userCanApprove?: boolean;
}

export default function PendenciasRepasse({ productId, userCanApprove = true }: PendenciasRepasseProps) {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [selectedPendencia, setSelectedPendencia] = useState<number | null>(null);

  const { data: pendencias = [], isLoading } = useQuery({
    queryKey: ["pendencias-repasse", productId],
    queryFn: async () => {
      const url = productId ? `/api/pendencias-repasse?productId=${productId}` : "/api/pendencias-repasse";
      const response = await fetch(url);
      if (!response.ok) return [];
      return response.json() as Promise<PendenciaRepasse[]>;
    }
  });

  // Smart cost impact calculations
  const calculateImpactMetrics = (pendencia: PendenciaRepasse) => {
    const valorAnterior = parseFloat(pendencia.valorAnterior);
    const valorNovo = parseFloat(pendencia.valorNovo);
    const variacao = ((valorNovo - valorAnterior) / valorAnterior) * 100;

    // Mock data for demonstration - in real implementation, this would come from API
    const pesoComposicao = pendencia.pesoComposicao || Math.random() * 25; // % weight in total cost
    const impactoTotal = (variacao * pesoComposicao) / 100;
    const margemAtual = 15; // Mock current margin
    const novaMargemSugerida = margemAtual + impactoTotal;

    return {
      variacao: variacao.toFixed(1),
      pesoComposicao: pesoComposicao.toFixed(1),
      impactoTotal: impactoTotal.toFixed(2),
      margemSugerida: novaMargemSugerida.toFixed(1),
      criticidade: Math.abs(impactoTotal) > 2 ? 'alta' : Math.abs(impactoTotal) > 0.5 ? 'media' : 'baixa'
    };
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "aguardando":
        return <Badge variant="outline" className="text-amber-600 border-amber-600"><Clock className="h-3 w-3 mr-1" />Aguardando</Badge>;
      case "aprovado":
        return <Badge variant="outline" className="text-green-600 border-green-600"><Check className="h-3 w-3 mr-1" />Aprovado</Badge>;
      case "rejeitado":
        return <Badge variant="outline" className="text-red-600 border-red-600"><X className="h-3 w-3 mr-1" />Rejeitado</Badge>;
      default:
        return <Badge variant="outline">{status}</Badge>;
    }
  };

  const getCriticidadeBadge = (criticidade: string) => {
    switch (criticidade) {
      case 'alta':
        return <Badge variant="destructive" className="text-xs">Alto Impacto</Badge>;
      case 'media':
        return <Badge variant="outline" className="text-xs text-amber-600 border-amber-600">Médio Impacto</Badge>;
      case 'baixa':
        return <Badge variant="secondary" className="text-xs">Baixo Impacto</Badge>;
      default:
        return null;
    }
  };

  const approveMutation = useMutation({
    mutationFn: async (id: number) => {
      return apiRequest("POST", `/api/pendencias-repasse/${id}/approve`, {});
    },
    onSuccess: () => {
      toast({ title: "Pendência aprovada com sucesso!" });
      queryClient.invalidateQueries({ queryKey: ["pendencias-repasse"] });
    },
    onError: () => {
      toast({ title: "Erro ao aprovar pendência", variant: "destructive" });
    }
  });

  const rejectMutation = useMutation({
    mutationFn: async (id: number) => {
      return apiRequest("POST", `/api/pendencias-repasse/${id}/reject`, {});
    },
    onSuccess: () => {
      toast({ title: "Pendência rejeitada com sucesso!" });
      queryClient.invalidateQueries({ queryKey: ["pendencias-repasse"] });
    },
    onError: () => {
      toast({ title: "Erro ao rejeitar pendência", variant: "destructive" });
    }
  });

  const pendenciasAguardando = pendencias.filter(p => p.status === "aguardando");
  const hasBlockingPendencies = pendenciasAguardando.length > 0;
  const pendenciasAltoImpacto = pendenciasAguardando.filter(p => {
    const metrics = calculateImpactMetrics(p);
    return metrics.criticidade === 'alta';
  }).length;

  if (isLoading) {
    return (
      <Card className="mb-6">
        <CardContent className="p-6">
          <div className="text-center py-4">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-gray-900 mx-auto mb-2"></div>
            Carregando pendências...
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className={`mb-6 transition-all duration-300 ${hasBlockingPendencies ? 'border-amber-500 bg-gradient-to-r from-amber-50 to-orange-50 shadow-lg' : 'hover:shadow-md'}`}>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          {hasBlockingPendencies && <AlertTriangle className="h-5 w-5 text-amber-600" />}
          <span className="flex items-center gap-2">
            <Calculator className="h-5 w-5" />
            Pedências de Repasse de Custos
          </span>
          {hasBlockingPendencies && (
            <div className="flex gap-2">
              <Badge variant="outline" className="text-amber-600 border-amber-600">
                {pendenciasAguardando.length} pendente{pendenciasAguardando.length > 1 ? 's' : ''}
              </Badge>
              {pendenciasAltoImpacto > 0 && (
                <Badge variant="destructive" className="animate-pulse">
                  {pendenciasAltoImpacto} crítica{pendenciasAltoImpacto > 1 ? 's' : ''}
                </Badge>
              )}
            </div>
          )}
        </CardTitle>
        {hasBlockingPendencies && (
          <div className="bg-amber-100 border border-amber-200 rounded-lg p-3 mt-2">
            <p className="text-sm text-amber-800 font-medium">
              ⚠️ Atenção: {pendenciasAguardando.length} alteração{pendenciasAguardando.length > 1 ? 'ões' : ''} de custo aguardando aprovação
            </p>
            <p className="text-xs text-amber-700 mt-1">
              O sistema detectou mudanças nos custos de insumos. Analise o impacto percentual antes de aprovar.
            </p>
          </div>
        )}
      </CardHeader>
      <CardContent>
        {pendencias.length === 0 ? (
          <div className="text-center py-8 text-gray-500">
            <div className="bg-green-100 rounded-full p-4 w-20 h-20 mx-auto mb-4 flex items-center justify-center">
              <Check className="h-10 w-10 text-green-600" />
            </div>
            <h3 className="font-medium text-gray-900 mb-2">Tudo atualizado!</h3>
            <p className="text-sm">Nenhuma pendência de repasse encontrada</p>
          </div>
        ) : (
          <div className="space-y-4">
            {pendencias.map((pendencia) => {
              const metrics = calculateImpactMetrics(pendencia);
              const isPositiveChange = parseFloat(metrics.variacao) > 0;

              return (
                <div
                  key={pendencia.id}
                  className={`group border rounded-xl p-5 transition-all duration-300 hover:shadow-lg ${
                    pendencia.status === "aguardando" 
                      ? `border-l-4 ${metrics.criticidade === 'alta' ? 'border-l-red-500 bg-red-50' : metrics.criticidade === 'media' ? 'border-l-amber-500 bg-amber-50' : 'border-l-blue-500 bg-blue-50'}`
                      : "border-gray-200 hover:border-gray-300"
                  }`}
                >
                  {/* Header with insumo name and status */}
                  <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-3">
                      <div className="flex-shrink-0">
                        <div className={`p-2 rounded-lg ${
                          metrics.criticidade === 'alta' ? 'bg-red-100' : 
                          metrics.criticidade === 'media' ? 'bg-amber-100' : 'bg-blue-100'
                        }`}>
                          {isPositiveChange ? 
                            <TrendingUp className={`h-4 w-4 ${
                              metrics.criticidade === 'alta' ? 'text-red-600' : 
                              metrics.criticidade === 'media' ? 'text-amber-600' : 'text-blue-600'
                            }`} /> :
                            <TrendingDown className="h-4 w-4 text-green-600" />
                          }
                        </div>
                      </div>
                      <div>
                        <h4 className="font-semibold text-gray-900">{pendencia.insumoNome}</h4>
                        <p className="text-sm text-gray-600">{pendencia.productNome}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      {getCriticidadeBadge(metrics.criticidade)}
                      {getStatusBadge(pendencia.status)}
                    </div>
                  </div>

                  {/* Impact Analysis Cards */}
                  <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-4">
                    <div className="bg-white rounded-lg p-3 border border-gray-100">
                      <div className="flex items-center gap-2 mb-1">
                        <Percent className="h-3 w-3 text-gray-500" />
                        <span className="text-xs font-medium text-gray-500">VARIAÇÃO</span>
                      </div>
                      <p className={`text-lg font-bold ${isPositiveChange ? 'text-red-600' : 'text-green-600'}`}>
                        {isPositiveChange ? '+' : ''}{metrics.variacao}%
                      </p>
                    </div>

                    <div className="bg-white rounded-lg p-3 border border-gray-100">
                      <div className="flex items-center gap-2 mb-1">
                        <Calculator className="h-3 w-3 text-gray-500" />
                        <span className="text-xs font-medium text-gray-500">PESO NA COMPOSIÇÃO</span>
                      </div>
                      <p className="text-lg font-bold text-gray-900">{metrics.pesoComposicao}%</p>
                      <Progress value={parseFloat(metrics.pesoComposicao)} className="h-1 mt-1" />
                    </div>

                    <div className="bg-white rounded-lg p-3 border border-gray-100">
                      <div className="flex items-center gap-2 mb-1">
                        <TrendingUp className="h-3 w-3 text-gray-500" />
                        <span className="text-xs font-medium text-gray-500">IMPACTO TOTAL</span>
                      </div>
                      <p className={`text-lg font-bold ${Math.abs(parseFloat(metrics.impactoTotal)) > 2 ? 'text-red-600' : Math.abs(parseFloat(metrics.impactoTotal)) > 0.5 ? 'text-amber-600' : 'text-green-600'}`}>
                        {parseFloat(metrics.impactoTotal) > 0 ? '+' : ''}{metrics.impactoTotal}%
                      </p>
                    </div>

                    <div className="bg-white rounded-lg p-3 border border-gray-100">
                      <div className="flex items-center gap-2 mb-1">
                        <DollarSign className="h-3 w-3 text-gray-500" />
                        <span className="text-xs font-medium text-gray-500">MARGEM SUGERIDA</span>
                      </div>
                      <p className="text-lg font-bold text-blue-600">{metrics.margemSugerida}%</p>
                    </div>
                  </div>

                  {/* Value Change Details */}
                  <div className="bg-gray-50 rounded-lg p-3 mb-4">
                    <div className="flex items-center justify-between text-sm">
                      <div className="flex items-center gap-4">
                        <span className="text-gray-600">
                          <span className="font-medium">De:</span> R$ {pendencia.valorAnterior}
                        </span>
                        <span className="text-gray-400">→</span>
                        <span className="text-gray-600">
                          <span className="font-medium">Para:</span> R$ {pendencia.valorNovo}
                        </span>
                      </div>
                      <span className="text-xs text-gray-500">
                        Variação detectada em: {formatDistanceToNow(new Date(pendencia.createdAt), { addSuffix: true, locale: ptBR })}
                      </span>
                    </div>
                  </div>

                  {/* Action Buttons for Pending Items */}
                  {pendencia.status === "aguardando" && userCanApprove && (
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2 text-xs text-gray-500">
                        <span>Variação detectada em:</span>
                        <span className="font-medium">{formatDistanceToNow(new Date(pendencia.createdAt), { addSuffix: true, locale: ptBR })}</span>
                      </div>
                      <div className="flex gap-2">
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => rejectMutation.mutate(pendencia.id)}
                          disabled={rejectMutation.isPending}
                          className="text-red-600 border-red-200 hover:bg-red-50"
                        >
                          <X className="h-3 w-3 mr-1" />
                          Rejeitar
                        </Button>
                        <Button
                          size="sm"
                          onClick={() => approveMutation.mutate(pendencia.id)}
                          disabled={approveMutation.isPending}
                          className="bg-green-600 hover:bg-green-700"
                        >
                          <Check className="h-3 w-3 mr-1" />
                          {metrics.criticidade === 'alta' ? 'Aprovar (Alto Risco)' : 'Aprovar Repasse'}
                        </Button>
                      </div>
                    </div>
                  )}

                  {pendencia.status !== "aguardando" && (
                    <div className="flex items-center justify-between">
                      <div className="text-xs text-gray-500">
                        <span>Variação detectada em: {formatDistanceToNow(new Date(pendencia.createdAt), { addSuffix: true, locale: ptBR })}</span>
                        {pendencia.approvedAt && (
                          <span className="ml-4">
                            Processado: {formatDistanceToNow(new Date(pendencia.approvedAt), { addSuffix: true, locale: ptBR })}
                          </span>
                        )}
                      </div>
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => setSelectedPendencia(selectedPendencia === pendencia.id ? null : pendencia.id)}
                      >
                        <Eye className="h-4 w-4" />
                      </Button>
                    </div>
                  )}

                  {selectedPendencia === pendencia.id && pendencia.status !== "aguardando" && (
                    <div className="mt-3 pt-3 border-t border-gray-200 text-xs text-gray-500">
                      {pendencia.status === "aprovado" && pendencia.approvedAt && (
                        <p>Aprovado em {formatDistanceToNow(new Date(pendencia.approvedAt), { addSuffix: true, locale: ptBR })}</p>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

client/src/components/pricing-configurat.content:
import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Save, Edit, Lock, Handshake, Building, CreditCard, Truck, Receipt } from "lucide-react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";

interface PricingConfigurationProps {
  productId: number;
  userCanEdit?: boolean;
}

interface PricingConfig {
  id?: number;
  productId: number;
  acordosContratuais: string;
  contratuaisPercent: string;
  tradeMarketingPercent: string;
  comissoesPercent: string;
  despesasGeraisAdm: string;
  prazoPagamentoDias: number;
  jurosAm: string;
  encargosPercent: string;
  armazenagemPercent: string;
  margemPercent: string;
  icmsPercent: string;
  pisPercent: string;
  cofinsPercent: string;
}

const defaultConfig: Partial<PricingConfig> = {
  acordosContratuais: "14.250",
  contratuaisPercent: "14.250",
  tradeMarketingPercent: "0.000",
  comissoesPercent: "0.000",
  despesasGeraisAdm: "10.500",
  prazoPagamentoDias: 30,
  jurosAm: "1.00",
  encargosPercent: "2.00",
  armazenagemPercent: "0.00",
  margemPercent: "10.000",
  icmsPercent: "7.000",
  pisPercent: "0.000",
  cofinsPercent: "0.000",
};

export default function PricingConfiguration({ productId, userCanEdit = false }: PricingConfigurationProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [config, setConfig] = useState<PricingConfig | null>(null);
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const { data: pricingConfig, isLoading } = useQuery({
    queryKey: [`pricing-config-${productId}`],
    queryFn: async () => {
      const response = await apiRequest("GET", `/api/products/${productId}/pricing-config`);
      return response.json();
    },
  });

  const updateConfigMutation = useMutation({
    mutationFn: async (newConfig: Partial<PricingConfig>) => {
      const response = await apiRequest("PUT", `/api/products/${productId}/pricing-config`, {
        ...newConfig,
        userId: 1, // In real app, get from user context
      });
      return response.json();
    },
    onSuccess: () => {
      toast({
        title: "Sucesso",
        description: "Configuração de preços atualizada com sucesso",
      });
      setIsEditing(false);
      queryClient.invalidateQueries({ queryKey: [`pricing-config-${productId}`] });
    },
    onError: () => {
      toast({
        title: "Erro",
        description: "Erro ao atualizar configuração de preços",
        variant: "destructive",
      });
    },
  });

  useEffect(() => {
    if (pricingConfig) {
      setConfig(pricingConfig);
    } else {
      setConfig({ productId, ...defaultConfig } as PricingConfig);
    }
  }, [pricingConfig, productId]);

  const handleSave = () => {
    if (config) {
      updateConfigMutation.mutate(config);
    }
  };

  const handleInputChange = (field: keyof PricingConfig, value: string | number) => {
    if (config) {
      setConfig({ ...config, [field]: value });
    }
  };

  if (isLoading) {
    return <div>Carregando configuração...</div>;
  }

  return (
    <Card className="mt-6">
      <CardHeader className="flex flex-row items-center justify-between">
        <CardTitle className="text-lg font-semibold text-gray-800 flex items-center gap-2">
          <Edit size={20} />
          Configuração de Preços
        </CardTitle>
        {userCanEdit && (
          <div className="flex gap-2">
            {isEditing ? (
              <>
                <Button 
                  variant="outline" 
                  onClick={() => setIsEditing(false)}
                  size="sm"
                >
                  Cancelar
                </Button>
                <Button 
                  onClick={handleSave}
                  disabled={updateConfigMutation.isPending}
                  size="sm"
                >
                  <Save size={16} className="mr-2" />
                  Salvar
                </Button>
              </>
            ) : (
              <Button 
                onClick={() => setIsEditing(true)}
                size="sm"
              >
                <Edit size={16} className="mr-2" />
                Editar
              </Button>
            )}
          </div>
        )}
        {!userCanEdit && (
          <div className="flex items-center gap-2 text-gray-500">
            <Lock size={16} />
            <span className="text-sm">Somente visualização</span>
          </div>
        )}
      </CardHeader>

      <CardContent className="space-y-6">
        {config && (
          <>
            {/* Acordos e Despesas */}
