import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Calculator, Info, Save, Edit, Lock } from "lucide-react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";

interface ExcelPricingSheetProps {
  productId: number;
  userCanEdit?: boolean;
}

interface PricingData {
  // Custos Fixos (R$)
  maoDeObra: string;
  manutencao: string;
  depreciacao: string;
  limpeza: string;
  laboratorio: string;

  // Custos Marginais (R$) - baseados na fórmula específica
  massa: string;
  insumosPesadinha: string;
  embalagem: string;

  // Impostos (%)
  icms: string;
  pis: string;
  cofins: string;

  // Despesas (%)
  administrativas: string;
  financeirasJuros: string;
  contratuais: string;
  tradeMarketing: string;
  comissoes: string;

  // Margem (%)
  margemDesejada: string;
}

const defaultPricingData: PricingData = {
  maoDeObra: "12.50",
  manutencao: "8.30",
  depreciacao: "15.75",
  limpeza: "5.20",
  laboratorio: "3.80",
  massa: "25.40",
  insumosPesadinha: "18.90",
  embalagem: "7.65",
  icms: "7.000",
  pis: "1.650",
  cofins: "7.600",
  administrativas: "8.500",
  financeirasJuros: "1.200",
  contratuais: "2.000",
  tradeMarketing: "1.500",
  comissoes: "0.800",
  margemDesejada: "15.000"
};

const tooltips = {
  maoDeObra: "Custo estimado de mão de obra por período dividido pela quantidade de itens produzidos.",
  manutencao: "Gastos com manutenção preventiva e corretiva dos equipamentos de produção.",
  depreciacao: "Valor da depreciação dos ativos utilizados na produção do item.",
  limpeza: "Custos com produtos de limpeza e sanitização necessários no processo produtivo.",
  laboratorio: "Gastos com análises laboratoriais e controle de qualidade do produto.",
  massa: "Calculado pela proporção usada neste produto em relação ao rendimento total do insumo principal.",
  insumosPesadinha: "Custo dos insumos menores (temperos, aditivos) calculados pela fórmula específica.",
  embalagem: "Custo das embalagens primária e secundária utilizadas no produto.",
  icms: "Imposto estadual aplicado sobre o preço de venda conforme legislação tributária.",
  pis: "Programa de Integração Social - contribuição federal sobre o faturamento.",
  cofins: "Contribuição para Financiamento da Seguridade Social sobre o faturamento.",
  administrativas: "Percentual das despesas administrativas gerais da empresa.",
  financeirasJuros: "Taxa de juros mensal aplicada sobre o capital de giro necessário.",
  contratuais: "Percentual destinado a acordos contratuais específicos com clientes.",
  tradeMarketing: "Investimentos em marketing trade e promoções comerciais.",
  comissoes: "Percentual destinado ao pagamento de comissões de vendas.",
  margemDesejada: "Percentual de lucro planejado sobre o custo total do produto."
};

export default function ExcelPricingSheet({ productId, userCanEdit = false }: ExcelPricingSheetProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [data, setData] = useState<PricingData>(defaultPricingData);
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const { data: product } = useQuery({
    queryKey: [`/api/products/${productId}`],
    enabled: !!productId,
  });

  const updatePricingMutation = useMutation({
    mutationFn: async (newData: PricingData) => {
      const response = await apiRequest("PUT", `/api/products/${productId}/excel-pricing`, {
        ...newData,
        userId: 1,
      });
      return response.json();
    },
    onSuccess: () => {
      toast({
        title: "Sucesso",
        description: "Planilha de precificação atualizada com sucesso",
      });
      setIsEditing(false);
      queryClient.invalidateQueries({ queryKey: [`/api/products/${productId}`] });
    },
    onError: () => {
      toast({
        title: "Erro",
        description: "Erro ao atualizar planilha de precificação",
        variant: "destructive",
      });
    },
  });

  const handleSave = () => {
    updatePricingMutation.mutate(data);
  };

  const handleInputChange = (field: keyof PricingData, value: string) => {
    setData({ ...data, [field]: value });
  };

  // Cálculos automáticos
  const custosFixosTotal = parseFloat(data.maoDeObra) + parseFloat(data.manutencao) + 
                          parseFloat(data.depreciacao) + parseFloat(data.limpeza) + parseFloat(data.laboratorio);

  const custosMarginaisTotal = parseFloat(data.massa) + parseFloat(data.insumosPesadinha) + parseFloat(data.embalagem);

  const custosTotal = custosFixosTotal + custosMarginaisTotal;

  const impostosTotal = parseFloat(data.icms) + parseFloat(data.pis) + parseFloat(data.cofins);

  const despesasTotal = parseFloat(data.administrativas) + parseFloat(data.financeirasJuros) + 
                       parseFloat(data.contratuais) + parseFloat(data.tradeMarketing) + parseFloat(data.comissoes);

  const precoVenda = custosTotal / (1 - (impostosTotal + despesasTotal + parseFloat(data.margemDesejada)) / 100);

  const FieldRow = ({ 
    label, 
    field, 
    value, 
    isPercent = false, 
    tooltip 
  }: { 
    label: string;
    field: keyof PricingData;
    value: string;
    isPercent?: boolean;
    tooltip: string;
  }) => {
    const numValue = parseFloat(value);
    const percentOfTotal = custosTotal > 0 ? (numValue / custosTotal * 100) : 0;

    return (
      <tr className="border-b border-gray-100 hover:bg-gray-50">
        <td className="py-3 px-4 text-sm font-medium text-gray-700 flex items-center gap-2">
          {label}
          <TooltipProvider>
            <Tooltip>
              <TooltipTrigger>
                <Info className="h-4 w-4 text-gray-400 hover:text-gray-600" />
              </TooltipTrigger>
              <TooltipContent className="max-w-sm">
                <p>{tooltip}</p>
              </TooltipContent>
            </Tooltip>
          </TooltipProvider>
        </td>
        <td className="py-3 px-4">
          <Input
            type="number"
            step="0.001"
            value={value}
            onChange={(e) => handleInputChange(field, e.target.value)}
            disabled={!isEditing}
            className={`text-right ${!isEditing ? "bg-gray-50 border-gray-200" : "border-blue-300"}`}
          />
        </td>
        <td className="py-3 px-4 text-right text-sm">
          <Badge variant="secondary">
            {isPercent ? "%" : "R$"}
          </Badge>
        </td>
        <td className="py-3 px-4 text-right text-sm text-gray-600">
          {!isPercent && percentOfTotal.toFixed(2)}%
        </td>
      </tr>
    );
  };

  return (
    <Card className="mb-8 shadow-sm border border-gray-200">
      <CardHeader className="flex flex-row items-center justify-between">
        <CardTitle className="text-lg font-semibold text-gray-800 flex items-center gap-2">
          <Calculator className="text-corporate" size={20} />
          Planilha de Precificação
          <Badge variant="outline" className="ml-2">Excel Style</Badge>
        </CardTitle>
        {userCanEdit && (
          <div className="flex gap-2">
            {isEditing ? (
              <>
                <Button 
                  variant="outline" 
                  size="sm"
                  onClick={() => setIsEditing(false)}
                >
                  Cancelar
                </Button>
                <Button 
                  size="sm"
                  onClick={handleSave}
                  disabled={updatePricingMutation.isPending}
                >
                  <Save className="h-4 w-4 mr-1" />
                  Salvar
                </Button>
              </>
            ) : (
              <Button 
                variant="outline" 
                size="sm"
                onClick={() => setIsEditing(true)}
              >
                <Edit className="h-4 w-4 mr-1" />
                Editar
              </Button>
            )}
          </div>
        )}
      </CardHeader>

      <CardContent className="p-0">
        <div className="overflow-x-auto">
          {/* Custos Fixos */}
          <div className="border-b-4 border-corporate bg-gray-50 px-6 py-3">
            <h3 className="font-semibold text-corporate text-lg">
              💼 CUSTOS FIXOS (OPERACIONAIS)
            </h3>
            <p className="text-sm text-gray-600">Valores absolutos em R$, sem percentual</p>
          </div>

          <table className="w-full">
            <thead className="bg-gray-100">
              <tr>
                <th className="py-3 px-4 text-left text-sm font-medium text-gray-600 w-1/3">Campo</th>
                <th className="py-3 px-4 text-right text-sm font-medium text-gray-600 w-1/4">Valor</th>
                <th className="py-3 px-4 text-center text-sm font-medium text-gray-600 w-1/6">Unidade</th>
                <th className="py-3 px-4 text-right text-sm font-medium text-gray-600 w-1/4">% do Total</th>
              </tr>
            </thead>
            <tbody>
              <FieldRow label="Mão de Obra" field="maoDeObra" value={data.maoDeObra} tooltip={tooltips.maoDeObra} />
              <FieldRow label="Manutenção" field="manutencao" value={data.manutencao} tooltip={tooltips.manutencao} />
              <FieldRow label="Depreciação" field="depreciacao" value={data.depreciacao} tooltip={tooltips.depreciacao} />
              <FieldRow label="Limpeza" field="limpeza" value={data.limpeza} tooltip={tooltips.limpeza} />
              <FieldRow label="Laboratório" field="laboratorio" value={data.laboratorio} tooltip={tooltips.laboratorio} />
            </tbody>
          </table>

          <div className="bg-blue-50 px-6 py-3 border-b">
            <div className="flex justify-between items-center">
              <span className="font-semibold text-blue-800">SUBTOTAL CUSTOS FIXOS</span>
              <span className="font-bold text-blue-800 text-lg">R$ {custosFixosTotal.toFixed(2)}</span>
            </div>
          </div>

          {/* Custos Marginais */}
          <div className="border-b-4 border-orange-500 bg-orange-50 px-6 py-3">
            <h3 className="font-semibold text-orange-700 text-lg">
              🔄 CUSTOS MARGINAIS (VARIÁVEIS)
            </h3>
            <p className="text-sm text-gray-600">
              Fórmula: (Qtd. em kg ÷ Rendimento) × (Valor compra ÷ Qtd. total kg do lote)
            </p>
          </div>

          <table className="w-full">
            <thead className="bg-orange-100">
              <tr>
                <th className="py-3 px-4 text-left text-sm font-medium text-gray-600 w-1/3">Campo</th>
                <th className="py-3 px-4 text-right text-sm font-medium text-gray-600 w-1/4">Valor</th>
                <th className="py-3 px-4 text-center text-sm font-medium text-gray-600 w-1/6">Unidade</th>
                <th className="py-3 px-4 text-right text-sm font-medium text-gray-600 w-1/4">% do Total</th>
              </tr>
            </thead>
            <tbody>
              <FieldRow label="Massa" field="massa" value={data.massa} tooltip={tooltips.massa} />
              <FieldRow label="Insumos (Pesadinha)" field="insumosPesadinha" value={data.insumosPesadinha} tooltip={tooltips.insumosPesadinha} />
              <FieldRow label="Embalagem" field="embalagem" value={data.embalagem} tooltip={tooltips.embalagem} />
            </tbody>
          </table>

          <div className="bg-orange-50 px-6 py-3 border-b">
            <div className="flex justify-between items-center">
              <span className="font-semibold text-orange-800">SUBTOTAL CUSTOS MARGINAIS</span>
              <span className="font-bold text-orange-800 text-lg">R$ {custosMarginaisTotal.toFixed(2)}</span>
            </div>
          </div>

          {/* Impostos */}
          <div className="border-b-4 border-red-500 bg-red-50 px-6 py-3">
            <h3 className="font-semibold text-red-700 text-lg">
              📊 IMPOSTOS (%)
            </h3>
          </div>

          <table className="w-full">
            <thead className="bg-red-100">
              <tr>
                <th className="py-3 px-4 text-left text-sm font-medium text-gray-600 w-1/3">Campo</th>
                <th className="py-3 px-4 text-right text-sm font-medium text-gray-600 w-1/4">Valor</th>
                <th className="py-3 px-4 text-center text-sm font-medium text-gray-600 w-1/6">Unidade</th>
                <th className="py-3 px-4 text-right text-sm font-medium text-gray-600 w-1/4">% do Total</th>
              </tr>
            </thead>
            <tbody>
              <FieldRow label="ICMS" field="icms" value={data.icms} isPercent={true} tooltip={tooltips.icms} />
              <FieldRow label="PIS" field="pis" value={data.pis} isPercent={true} tooltip={tooltips.pis} />
              <FieldRow label="COFINS" field="cofins" value={data.cofins} isPercent={true} tooltip={tooltips.cofins} />
            </tbody>
          </table>

          {/* Despesas */}
          <div className="border-b-4 border-purple-500 bg-purple-50 px-6 py-3">
            <h3 className="font-semibold text-purple-700 text-lg">
              💳 DESPESAS (%)
            </h3>
          </div>

          <table className="w-full">
            <thead className="bg-purple-100">
              <tr>
                <th className="py-3 px-4 text-left text-sm font-medium text-gray-600 w-1/3">Campo</th>
                <th className="py-3 px-4 text-right text-sm font-medium text-gray-600 w-1/4">Valor</th>
                <th className="py-3 px-4 text-center text-sm font-medium text-gray-600 w-1/6">Unidade</th>
                <th className="py-3 px-4 text-right text-sm font-medium text-gray-600 w-1/4">% do Total</th>
              </tr>
            </thead>
            <tbody>
              <FieldRow label="Administrativas" field="administrativas" value={data.administrativas} isPercent={true} tooltip={tooltips.administrativas} />
              <FieldRow label="Financeiras (Juros a.m.)" field="financeirasJuros" value={data.financeirasJuros} isPercent={true} tooltip={tooltips.financeirasJuros} />
              <FieldRow label="Contratuais" field="contratuais" value={data.contratuais} isPercent={true} tooltip={tooltips.contratuais} />
              <FieldRow label="Trade Marketing" field="tradeMarketing" value={data.tradeMarketing} isPercent={true} tooltip={tooltips.tradeMarketing} />
              <FieldRow label="Comissões" field="comissoes" value={data.comissoes} isPercent={true} tooltip={tooltips.comissoes} />
            </tbody>
          </table>

          {/* Margem */}
          <div className="border-b-4 border-green-500 bg-green-50 px-6 py-3">
            <h3 className="font-semibold text-green-700 text-lg">
              💰 MARGEM DESEJADA (%)
            </h3>
          </div>

          <table className="w-full">
            <thead className="bg-green-100">
              <tr>
                <th className="py-3 px-4 text-left text-sm font-medium text-gray-600 w-1/3">Campo</th>
                <th className="py-3 px-4 text-right text-sm font-medium text-gray-600 w-1/4">Valor</th>
                <th className="py-3 px-4 text-center text-sm font-medium text-gray-600 w-1/6">Unidade</th>
                <th className="py-3 px-4 text-right text-sm font-medium text-gray-600 w-1/4">% do Total</th>
              </tr>
            </thead>
            <tbody>
              <FieldRow label="Margem Desejada" field="margemDesejada" value={data.margemDesejada} isPercent={true} tooltip={tooltips.margemDesejada} />
            </tbody>
          </table>

          <Separator className="my-6" />

          {/* Fórmula Final */}
          <div className="bg-gradient-to-r from-corporate to-blue-600 text-white px-6 py-6">
            <h3 className="text-xl font-bold mb-4 flex items-center gap-2">
              <Calculator className="h-6 w-6" />
              FÓRMULA FINAL DE PRECIFICAÇÃO
            </h3>

            <div className="bg-white/10 rounded-lg p-4 mb-4">
              <p className="text-lg font-mono">
                Preço de Venda = (Custos Fixos + Custos Marginais) ÷ (1 − (Impostos + Despesas + Margem))
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 text-center">
              <div className="bg-white/20 rounded-lg p-4">
                <p className="text-sm opacity-90">Custos Totais</p>
                <p className="text-2xl font-bold">R$ {custosTotal.toFixed(2)}</p>
              </div>
              <div className="bg-white/20 rounded-lg p-4">
                <p className="text-sm opacity-90">Impostos + Despesas + Margem</p>
                <p className="text-2xl font-bold">{(impostosTotal + despesasTotal + parseFloat(data.margemDesejada)).toFixed(1)}%</p>
              </div>
              <div className="bg-white/20 rounded-lg p-4">
                <p className="text-sm opacity-90">PREÇO DE VENDA</p>
                <p className="text-3xl font-bold text-yellow-300">R$ {precoVenda.toFixed(2)}</p>
              </div>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

