import { pgTable, serial, text, numeric, boolean, timestamp, integer } from 'drizzle-orm/pg-core';
import { sql } from 'drizzle-orm';

// Tabela de administradores
export const administrators = pgTable('administrators', {
  id: serial('id').primaryKey(),
  name: text('name').notNull(),
  accessCode: text('access_code').notNull().unique(),
  isActive: boolean('is_active').notNull().default(true),
  userType: text('user_type').notNull().default('admin'),
  createdAt: timestamp('created_at').default(sql`now()`),
});

// Tabela de produtos
export const products = pgTable('products', {
  id: serial('id').primaryKey(),
  code: text('code').notNull().unique(),
  name: text('name').notNull(),
  category: text('category').notNull(),
  kgPerUnit: numeric('kg_per_unit', { precision: 10, scale: 3 }).notNull(),
  yieldPercentage: numeric('yield_percentage', { precision: 5, scale: 2 }).notNull(),
  purchaseValue: numeric('purchase_value', { precision: 10, scale: 2 }).notNull(),
  costPerKg: numeric('cost_per_kg', { precision: 10, scale: 2 }).notNull(),
  status: text('status').notNull().default('pending'),
  caixasPorPalete: integer('caixas_por_palete'),
  pesoLiquidoPorCaixa: numeric('peso_liquido_por_caixa', { precision: 10, scale: 3 }),
  comprimentoCaixa: numeric('comprimento_caixa', { precision: 10, scale: 2 }),
  larguraCaixa: numeric('largura_caixa', { precision: 10, scale: 2 }),
  alturaCaixa: numeric('altura_caixa', { precision: 10, scale: 2 }),
  createdAt: timestamp('created_at').default(sql`now()`),
});

// Tabela de insumos - ATUALIZADA (sem yieldPercentage e finalCostPerKg)
export const insumos = pgTable('insumos', {
  id: serial('id').primaryKey(),
  code: text('code').notNull().unique(),
  name: text('name').notNull(),
  category: text('category').notNull(),
  unit: text('unit').notNull(),
  purchasePrice: numeric('purchase_price', { precision: 10, scale: 2 }).notNull(),
  createdAt: timestamp('created_at').default(sql`now()`),
});

// Tabela de pedidos - NOVA
export const pedidos = pgTable('pedidos', {
  id: serial('id').primaryKey(),
  numeropedido: text('numero_pedido').notNull().unique(),
  clienteId: integer('cliente_id'),
  status: text('status').notNull().default('pendente'),
  dataEntrega: timestamp('data_entrega'),
  observacoes: text('observacoes'),
  createdAt: timestamp('created_at').default(sql`now()`),
  updatedAt: timestamp('updated_at').default(sql`now()`),
});

// Tabela de detalhes dos pedidos - NOVA (com yieldPercentage)
export const pedidosDetalhes = pgTable('pedidos_detalhes', {
  id: serial('id').primaryKey(),
  pedidoId: integer('pedido_id').notNull(),
  productId: integer('product_id').notNull(),
  insumoId: integer('insumo_id').notNull(),
  quantidade: numeric('quantidade', { precision: 10, scale: 3 }).notNull(),
  yieldPercentage: numeric('yield_percentage', { precision: 5, scale: 2 }).notNull(),
  createdAt: timestamp('created_at').default(sql`now()`),
});

// Tabelas auxiliares para cálculo de preços - NOVAS

// Custos fixos
export const custosFixos = pgTable('custos_fixos', {
  id: serial('id').primaryKey(),
  nome: text('nome').notNull(),
  valor: numeric('valor', { precision: 10, scale: 2 }).notNull(),
  tipo: text('tipo').notNull(),
  ativo: boolean('ativo').notNull().default(true),
  createdAt: timestamp('created_at').default(sql`now()`),
});

// Despesas
export const despesas = pgTable('despesas', {
  id: serial('id').primaryKey(),
  nome: text('nome').notNull(),
  percentual: numeric('percentual', { precision: 5, scale: 2 }).notNull(),
  tipo: text('tipo').notNull(),
  ativo: boolean('ativo').notNull().default(true),
  createdAt: timestamp('created_at').default(sql`now()`),
});

// Impostos
export const impostos = pgTable('impostos', {
  id: serial('id').primaryKey(),
  nome: text('nome').notNull(),
  percentual: numeric('percentual', { precision: 5, scale: 2 }).notNull(),
  tipo: text('tipo').notNull(),
  ativo: boolean('ativo').notNull().default(true),
  createdAt: timestamp('created_at').default(sql`now()`),
});

// Margens
export const margens = pgTable('margens', {
  id: serial('id').primaryKey(),
  nome: text('nome').notNull(),
  percentual: numeric('percentual', { precision: 5, scale: 2 }).notNull(),
  minimo: numeric('minimo', { precision: 5, scale: 2 }).notNull(),
  maximo: numeric('maximo', { precision: 5, scale: 2 }).notNull(),
  ativo: boolean('ativo').notNull().default(true),
  createdAt: timestamp('created_at').default(sql`now()`),
});

// Logística de armazenagem
export const logisticaArmazenagem = pgTable('logistica_armazenagem', {
  id: serial('id').primaryKey(),
  nome: text('nome').notNull(),
  custoPorKg: numeric('custo_por_kg', { precision: 10, scale: 2 }).notNull(),
  tipo: text('tipo').notNull(),
  ativo: boolean('ativo').notNull().default(true),
  createdAt: timestamp('created_at').default(sql`now()`),
});

// Tabelas existentes que mantemos
export const productInsumos = pgTable('product_insumos', {
  id: serial('id').primaryKey(),
  productId: integer('product_id').notNull(),
  insumoId: integer('insumo_id').notNull(),
  quantity: numeric('quantity', { precision: 10, scale: 3 }),
  createdAt: timestamp('created_at').default(sql`now()`),
});

export const logAlteracoes = pgTable('log_alteracoes', {
  id: serial('id').primaryKey(),
  productId: integer('product_id'),
  insumoId: integer('insumo_id'),
  changeType: text('change_type').notNull(),
  previousValue: text('previous_value'),
  newValue: text('new_value'),
  userId: integer('user_id').notNull(),
  description: text('description'),
  createdAt: timestamp('created_at').default(sql`now()`),
});

export const pendenciasRepasse = pgTable('pendencias_repasse', {
  id: serial('id').primaryKey(),
  insumoId: integer('insumo_id').notNull(),
  productId: integer('product_id').notNull(),
  valorAnterior: numeric('valor_anterior', { precision: 10, scale: 2 }).notNull(),
  valorNovo: numeric('valor_novo', { precision: 10, scale: 2 }).notNull(),
  percentualVariacao: numeric('percentual_variacao', { precision: 5, scale: 2 }).notNull(),
  impactoNoPreco: numeric('impacto_no_preco', { precision: 10, scale: 2 }).notNull(),
  status: text('status').notNull().default('pendente'),
  userId: integer('user_id').notNull(),
  approvedBy: integer('approved_by'),
  rejectedBy: integer('rejected_by'),
  createdAt: timestamp('created_at').default(sql`now()`),
  approvedAt: timestamp('approved_at'),
  rejectedAt: timestamp('rejected_at'),
});

export const userPermissions = pgTable('user_permissions', {
  id: serial('id').primaryKey(),
  userId: integer('user_id').notNull(),
  canEdit: boolean('can_edit').notNull().default(false),
  canApprove: boolean('can_approve').notNull().default(false),
  canView: boolean('can_view_sensitive').notNull().default(true),
  createdAt: timestamp('created_at').default(sql`now()`),
});

export const pricingConfiguration = pgTable('pricing_configuration', {
  id: serial('id').primaryKey(),
  productId: integer('product_id').notNull(),
  margemMinimaPermitida: numeric('margem_minima_permitida', { precision: 5, scale: 3 }),
  autoApprovalThreshold: numeric('auto_approval_threshold', { precision: 5, scale: 3 }),
  requiresApprovalAbove: numeric('requires_approval_above', { precision: 5, scale: 3 }),
  updatedBy: integer('updated_by'),
  createdAt: timestamp('created_at').default(sql`now()`),
});

// Tabelas de logística e transporte existentes
export const logisticaTransporte = pgTable('logistica_transporte', {
  id: serial('id').primaryKey(),
  productId: integer('product_id').notNull(),
  tipoTransporte: text('tipo_transporte').notNull(),
  valorTransporte: numeric('valor_transporte', { precision: 10, scale: 2 }).notNull(),
  observacoes: text('observacoes'),
  createdAt: timestamp('created_at').default(sql`now()`),
});

export const composicaoDetalhada = pgTable('composicao_detalhada', {
  id: serial('id').primaryKey(),
  productId: integer('product_id').notNull(),
  categoria: text('categoria').notNull(),
  custoOperacional: numeric('custo_operacional', { precision: 10, scale: 2 }).notNull(),
  custoVendas: numeric('custo_vendas', { precision: 10, scale: 2 }).notNull(),
