import { eq, desc, and } from 'drizzle-orm';
import db from './db/connection';
import * as schema from './db/schema';
import { IStorage } from './storage';
import {
  Administrator,
  Product,
  Insumo,
  LogAlteracao,
  PendenciaRepasse,
  UserPermission,
  PricingConfiguration,
  LogisticaTransporte,
  ComposicaoDetalhada,
  ComposicaoPreco,
  PriceCalculationParams,
  PriceCalculationResult,
} from '../shared/schema';

export class PostgreSQLStorage implements IStorage {

  // Método para calcular preço dinâmico baseado na nova fórmula
  async calculateDynamicPrice(params: PriceCalculationParams): Promise<PriceCalculationResult> {
    const { insumoId, quantidade, yieldPercentage } = params;

    // Buscar dados do insumo
    const insumo = await db
      .select()
      .from(schema.insumos)
      .where(eq(schema.insumos.id, insumoId))
      .then(rows => rows[0]);

    if (!insumo) {
      throw new Error(`Insumo com ID ${insumoId} não encontrado`);
    }

    // Buscar custos fixos ativos
    const custosFixos = await db
      .select()
      .from(schema.custosFixos)
      .where(eq(schema.custosFixos.ativo, true));

    // Buscar despesas ativas
    const despesas = await db
      .select()
      .from(schema.despesas)
      .where(eq(schema.despesas.ativo, true));

    // Buscar impostos ativos
    const impostos = await db
      .select()
      .from(schema.impostos)
      .where(eq(schema.impostos.ativo, true));

    // Buscar margens ativas
    const margens = await db
      .select()
      .from(schema.margens)
      .where(eq(schema.margens.ativo, true));

    // Buscar logística de armazenagem ativa
    const logisticaArmazenagem = await db
      .select()
      .from(schema.logisticaArmazenagem)
      .where(eq(schema.logisticaArmazenagem.ativo, true));

    // Cálculos
    const custoInsumo = parseFloat(insumo.purchasePrice.toString());
    const rendimento = yieldPercentage / 100;
    const custoAjustadoRendimento = custoInsumo / rendimento;
    const custoMarginal = custoAjustadoRendimento * quantidade;

    const custoFixoTotal = custosFixos.reduce((total, custo) => 
      total + parseFloat(custo.valor.toString()), 0);

    const despesasPercentual = despesas.reduce((total, despesa) => 
      total + parseFloat(despesa.percentual.toString()), 0) / 100;

    const impostosPercentual = impostos.reduce((total, imposto) => 
      total + parseFloat(imposto.percentual.toString()), 0) / 100;

    const margemPercentual = margens.reduce((total, margem) => 
      total + parseFloat(margem.percentual.toString()), 0) / 100;

    const logisticaPercentual = logisticaArmazenagem.reduce((total, log) => 
      total + parseFloat(log.custoPorKg.toString()), 0) / 100;

    // Fórmula: (Custos Fixos + Custos Marginais) ÷ [1 - (Despesas + Impostos + Margem + Logística)]
    const numerador = custoFixoTotal + custoMarginal;
    const denominador = 1 - (despesasPercentual + impostosPercentual + margemPercentual + logisticaPercentual);

    if (denominador <= 0) {
      throw new Error('Denominador inválido: soma de percentuais maior ou igual a 100%');
    }

    const precoFinalPorKg = numerador / denominador;

    return {
      custoMarginal,
      custoFixoTotal,
      despesasPercentual: despesasPercentual * 100,
      impostosPercentual: impostosPercentual * 100,
      margemPercentual: margemPercentual * 100,
      logisticaArmazenagem: logisticaPercentual * 100,
      precoFinalPorKg,
      detalhes: {
        custoInsumo,
        custoAjustadoRendimento,
        denominador,
      },
    };
  }

  // Administrators
  async getAllAdministrators(): Promise<Administrator[]> {
    const result = await db.select().from(schema.administrators);
    return result.map(admin => ({
      ...admin,
      createdAt: new Date(admin.createdAt!),
    }));
  }

  async getAdministratorById(id: number): Promise<Administrator | undefined> {
    const result = await db
      .select()
      .from(schema.administrators)
      .where(eq(schema.administrators.id, id))
      .limit(1);

    return result.length > 0 ? {
      ...result[0],
      createdAt: new Date(result[0].createdAt!),
    } : undefined;
  }

  async getAdministratorByAccessCode(accessCode: string): Promise<Administrator | undefined> {
    const result = await db
      .select()
      .from(schema.administrators)
      .where(eq(schema.administrators.accessCode, accessCode))
      .limit(1);

    return result.length > 0 ? {
      ...result[0],
      createdAt: new Date(result[0].createdAt!),
    } : undefined;
  }

  async createAdministrator(admin: Omit<Administrator, 'id' | 'createdAt'>): Promise<Administrator> {
    const result = await db
      .insert(schema.administrators)
      .values({
        name: admin.name,
        accessCode: admin.accessCode,
        isActive: admin.isActive,
        userType: admin.userType,
      })
      .returning();

    return {
      ...result[0],
      createdAt: new Date(result[0].createdAt!),
    };
  }

  // Products
  async getAllProducts(): Promise<Product[]> {
    const result = await db.select().from(schema.products);
    return result.map(product => ({
      ...product,
      kgPerUnit: product.kgPerUnit?.toString() || '0',
      yieldPercentage: product.yieldPercentage?.toString() || '0',
      purchaseValue: product.purchaseValue?.toString() || '0',
      costPerKg: product.costPerKg?.toString() || '0',
      pesoLiquidoPorCaixa: product.pesoLiquidoPorCaixa?.toString() || '0',
      comprimentoCaixa: product.comprimentoCaixa?.toString() || '0',
      larguraCaixa: product.larguraCaixa?.toString() || '0',
      alturaCaixa: product.alturaCaixa?.toString() || '0',
      caixasPorPalete: product.caixasPorPalete || 0,
      createdAt: new Date(product.createdAt!),
    }));
  }

  async getProductById(id: number): Promise<Product | undefined> {
    const result = await db
      .select()
      .from(schema.products)
      .where(eq(schema.products.id, id))
      .limit(1);

    return result.length > 0 ? {
      ...result[0],
      kgPerUnit: result[0].kgPerUnit?.toString() || '0',
      yieldPercentage: result[0].yieldPercentage?.toString() || '0',
      purchaseValue: result[0].purchaseValue?.toString() || '0',
      costPerKg: result[0].costPerKg?.toString() || '0',
      pesoLiquidoPorCaixa: result[0].pesoLiquidoPorCaixa?.toString() || '0',
      comprimentoCaixa: result[0].comprimentoCaixa?.toString() || '0',
      larguraCaixa: result[0].larguraCaixa?.toString() || '0',
      alturaCaixa: result[0].alturaCaixa?.toString() || '0',
      caixasPorPalete: result[0].caixasPorPalete || 0,
      createdAt: new Date(result[0].createdAt!),
    } : undefined;
  }

  async createProduct(product: Omit<Product, 'id' | 'createdAt'>): Promise<Product> {
    const result = await db
      .insert(schema.products)
      .values({
        code: product.code,
        name: product.name,
        category: product.category,
        kgPerUnit: product.kgPerUnit,
        yieldPercentage: product.yieldPercentage,
        purchaseValue: product.purchaseValue,
        costPerKg: product.costPerKg,
        status: product.status,
        caixasPorPalete: product.caixasPorPalete,
        pesoLiquidoPorCaixa: product.pesoLiquidoPorCaixa,
        comprimentoCaixa: product.comprimentoCaixa,
        larguraCaixa: product.larguraCaixa,
        alturaCaixa: product.alturaCaixa,
      })
      .returning();

    return {
      ...result[0],
      kgPerUnit: result[0].kgPerUnit?.toString() || '0',
      yieldPercentage: result[0].yieldPercentage?.toString() || '0',
      purchaseValue: result[0].purchaseValue?.toString() || '0',
      costPerKg: result[0].costPerKg?.toString() || '0',
      pesoLiquidoPorCaixa: result[0].pesoLiquidoPorCaixa?.toString() || '0',
      comprimentoCaixa: result[0].comprimentoCaixa?.toString() || '0',
      larguraCaixa: result[0].larguraCaixa?.toString() || '0',
      alturaCaixa: result[0].alturaCaixa?.toString() || '0',
      caixasPorPalete: result[0].caixasPorPalete || 0,
      createdAt: new Date(result[0].createdAt!),
    };
  }

  // Insumos - ATUALIZADO para nova estrutura
  async getAllInsumos(): Promise<Insumo[]> {
    // Buscar apenas insumos que estão conectados a produtos
    const result = await db
      .selectDistinct({
        id: schema.insumos.id,
        code: schema.insumos.code,
        name: schema.insumos.name,
        category: schema.insumos.category,
        unit: schema.insumos.unit,
        purchasePrice: schema.insumos.purchasePrice,
        createdAt: schema.insumos.createdAt,
      })
      .from(schema.insumos)
      .innerJoin(schema.productInsumos, eq(schema.insumos.id, schema.productInsumos.insumoId));

    return result.map(insumo => ({
      id: insumo.id,
      code: insumo.code,
      name: insumo.name,
      category: insumo.category,
      unit: insumo.unit,
      purchasePrice: insumo.purchasePrice || 0,
      createdAt: new Date(insumo.createdAt!),
    }));
  }

  async getInsumoById(id: number): Promise<Insumo | undefined> {
    const result = await db
      .select()
      .from(schema.insumos)
      .where(eq(schema.insumos.id, id))
      .limit(1);

    return result.length > 0 ? {
      id: result[0].id,
      code: result[0].code,
      name: result[0].name,
      category: result[0].category,
      unit: result[0].unit,
      purchaseValue: result[0].purchasePrice?.toString() || '0',
      yieldPercentage: '100',
      finalCostPerKg: result[0].purchasePrice?.toString() || '0',
      createdAt: new Date(result[0].createdAt!),
    } : undefined;
  }

  async createInsumo(insumo: Omit<Insumo, 'id' | 'createdAt'>): Promise<Insumo> {
    const result = await db
      .insert(schema.insumos)
      .values({
        code: insumo.code,
        name: insumo.name,
        category: insumo.category,
        unit: insumo.unit,
        purchasePrice: parseFloat(insumo.purchaseValue),
      })
      .returning();

    return {
      id: result[0].id,
      code: result[0].code,
      name: result[0].name,
      category: result[0].category,
      unit: result[0].unit,
      purchaseValue: result[0].purchasePrice?.toString() || '0',
      yieldPercentage: '100',
      finalCostPerKg: result[0].purchasePrice?.toString() || '0',
      createdAt: new Date(result[0].createdAt!),
    };
  }

  // Log de alterações
  async getAllChanges(): Promise<LogAlteracao[]> {
    const result = await db
      .select()
      .from(schema.logAlteracoes)
      .orderBy(desc(schema.logAlteracoes.createdAt));

    return result.map(log => ({
      id: log.id,
      productId: log.productId || 0,
      userId: log.userId,
      changeType: log.changeType,
      description: log.description || '',
      previousValue: log.previousValue || '',
      newValue: log.newValue || '',
      insumoId: log.insumoId || undefined,
      createdAt: new Date(log.createdAt!),
    }));
  }

  async createLogAlteracao(log: Omit<LogAlteracao, 'id' | 'createdAt'>): Promise<LogAlteracao> {
    const result = await db
      .insert(schema.logAlteracoes)
      .values({
        productId: log.productId,
        insumoId: log.insumoId,
        changeType: log.changeType,
        previousValue: log.previousValue,
        newValue: log.newValue,
        userId: log.userId,
        description: log.description,
      })
      .returning();

    return {
      id: result[0].id,
      productId: result[0].productId || 0,
      userId: result[0].userId,
      changeType: result[0].changeType,
      description: result[0].description || '',
      previousValue: result[0].previousValue || '',
      newValue: result[0].newValue || '',
