      createdAt: new Date(result[0].createdAt!),
    };
  }

  // Pendências de repasse
  async getAllPendenciasRepasse(): Promise<PendenciaRepasse[]> {
    const result = await db
      .select()
      .from(schema.pendenciasRepasse)
      .orderBy(desc(schema.pendenciasRepasse.createdAt));

    return result.map(pendencia => ({
