      percentualVariacao: parseFloat(pendencia.percentualVariacao.toString()),
      impactoNoPreco: parseFloat(pendencia.impactoNoPreco.toString()),
      status: pendencia.status,
      userId: pendencia.userId,
      approvedBy: pendencia.approvedBy || undefined,
      rejectedBy: pendencia.rejectedBy || undefined,
      createdAt: new Date(pendencia.createdAt!),
      approvedAt: pendencia.approvedAt ? new Date(pendencia.approvedAt) : undefined,
      rejectedAt: pendencia.rejectedAt ? new Date(pendencia.rejectedAt) : undefined,
    }));
  }

  async getPendenciasRepasseByStatus(status: string): Promise<PendenciaRepasse[]> {
    const result = await db
