import { PriceCalculationParams, PriceCalculationResult } from '../shared/schema';

export class PriceCalculator {

  /**
   * Calcula o preço final baseado na nova fórmula:
   * (Custos Fixos + Custos Marginais) ÷ [1 - (Despesas + Impostos + Margem + Logística(Apenas armazenagem))]
   */
  static calculateDynamicPrice(params: {
    custoInsumo: number;
    quantidade: number;
    yieldPercentage: number;
    custosFixos: number[];
    despesasPercentuais: number[]; // em porcentagem (ex: 10 para 10%)
    impostosPercentuais: number[]; // em porcentagem
    margemPercentual: number; // em porcentagem
    logisticaArmazenagemPercentual: number; // em porcentagem
  }): PriceCalculationResult {

    const { 
      custoInsumo, 
      quantidade, 
      yieldPercentage, 
      custosFixos, 
      despesasPercentuais, 
      impostosPercentuais, 
      margemPercentual,
      logisticaArmazenagemPercentual 
    } = params;

    // Validações
    if (yieldPercentage <= 0 || yieldPercentage > 100) {
      throw new Error('Yield percentage deve estar entre 0 e 100');
    }

    // Cálculo do custo marginal (com ajuste de rendimento)
    const rendimento = yieldPercentage / 100;
    const custoAjustadoRendimento = custoInsumo / rendimento;
    const custoMarginal = custoAjustadoRendimento * quantidade;

    // Soma dos custos fixos
    const custoFixoTotal = custosFixos.reduce((total, custo) => total + custo, 0);

    // Soma dos percentuais
    const despesasTotal = despesasPercentuais.reduce((total, despesa) => total + despesa, 0);
    const impostosTotal = impostosPercentuais.reduce((total, imposto) => total + imposto, 0);

    // Conversão de percentuais para decimais
    const despesasDecimal = despesasTotal / 100;
    const impostosDecimal = impostosTotal / 100;
    const margemDecimal = margemPercentual / 100;
    const logisticaDecimal = logisticaArmazenagemPercentual / 100;

    // Fórmula: (Custos Fixos + Custos Marginais) ÷ [1 - (Despesas + Impostos + Margem + Logística)]
    const numerador = custoFixoTotal + custoMarginal;
    const denominador = 1 - (despesasDecimal + impostosDecimal + margemDecimal + logisticaDecimal);

    if (denominador <= 0) {
      throw new Error('Soma de percentuais (despesas + impostos + margem + logística) não pode ser maior ou igual a 100%');
    }

    const precoFinalPorKg = numerador / denominador;

    return {
      custoMarginal,
      custoFixoTotal,
      despesasPercentual: despesasTotal,
      impostosPercentual: impostosTotal,
      margemPercentual,
      logisticaArmazenagem: logisticaArmazenagemPercentual,
      precoFinalPorKg,
      detalhes: {
        custoInsumo,
        custoAjustadoRendimento,
        denominador,
      },
    };
  }

  /**
   * Versão simplificada para uso rápido com valores padrão
   */
  static calculateSimplePrice(
    custoInsumo: number, 
    quantidade: number, 
    yieldPercentage: number
  ): number {

    // Valores padrão do sistema
    const result = this.calculateDynamicPrice({
      custoInsumo,
      quantidade,
      yieldPercentage,
      custosFixos: [10.50], // Custo fixo padrão
      despesasPercentuais: [14.25], // Despesas gerais
      impostosPercentuais: [7.0], // ICMS padrão
      margemPercentual: 10.0, // Margem padrão
      logisticaArmazenagemPercentual: 2.0, // Armazenagem padrão
    });

    return result.precoFinalPorKg;
  }

  /**
   * Calcula preço com configuração personalizada por produto
   */
  static calculateWithProductConfig(
    custoInsumo: number,
    quantidade: number,
    yieldPercentage: number,
    productConfig: {
      despesasPercent?: number;
      impostosPercent?: number;
      margemPercent?: number;
      logisticaPercent?: number;
      custosFixos?: number[];
    }
  ): PriceCalculationResult {

    const config = {
      custosFixos: productConfig.custosFixos || [10.50],
      despesasPercentuais: [productConfig.despesasPercent || 14.25],
      impostosPercentuais: [productConfig.impostosPercent || 7.0],
      margemPercentual: productConfig.margemPercent || 10.0,
      logisticaArmazenagemPercentual: productConfig.logisticaPercent || 2.0,
    };

    return this.calculateDynamicPrice({
      custoInsumo,
      quantidade,
      yieldPercentage,
      ...config
    });
  }
}

