import { db } from './db';
import { sql } from 'drizzle-orm';
import fs from 'fs';
import path from 'path';
import {
  administrators,
  products,
  insumos,
  productInsumos,
  composicaoDetalhada,
  composicaoPreco,
  logisticaTransporte,
  logAlteracoes,
  pendenciasRepasse,
  logisticaModalidades,
  userPermissions,
  pricingConfiguration,
  simulacoesCenario,
  calculosLogistica,
  insumoVariacoes
} from '@shared/schema';

interface DatabaseData {
  administrators: any[];
  products: any[];
  insumos: any[];
  productInsumos: any[];
  composicaoDetalhada: any[];
  composicaoPreco: any[];
  logisticaTransporte: any[];
  logAlteracoes: any[];
  pendenciasRepasse: any[];
  logisticaModalidades: any[];
  simulacoesCenario: any[];
