import { useQuery } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Building, DollarSign, Users, FileText, Wrench, Wifi } from "lucide-react";

interface CustoFixo {
  id: number;
  nome: string;
  valor: string;
  tipo: string;
  ativo: boolean;
  created_at?: string;
}

const getTipoIcon = (tipo: string) => {
  switch (tipo.toLowerCase()) {
    case 'operacional':
      return <Building className="text-blue-600 mr-2" size={16} />;
    case 'pessoal':
      return <Users className="text-green-600 mr-2" size={16} />;
    case 'tributário':
      return <FileText className="text-red-600 mr-2" size={16} />;
    case 'administrativo':
      return <Wifi className="text-purple-600 mr-2" size={16} />;
    default:
      return <DollarSign className="text-gray-600 mr-2" size={16} />;
  }
};

const getTipoBorder = (tipo: string) => {
  switch (tipo.toLowerCase()) {
    case 'operacional':
      return 'border-l-4 border-blue-500';
    case 'pessoal':
      return 'border-l-4 border-green-500';
    case 'tributário':
      return 'border-l-4 border-red-500';
    case 'administrativo':
      return 'border-l-4 border-purple-500';
    default:
      return 'border-l-4 border-gray-500';
  }
};

export default function FixedCostSection() {
  const { data: custosFixos, isLoading, error } = useQuery<CustoFixo[]>({
    queryKey: ['/api/custos-fixos'],
    queryFn: async () => {
      const response = await fetch('/api/custos-fixos');
      if (!response.ok) {
        throw new Error('Failed to fetch custos fixos');
      }
      return response.json();
    },
    refetchOnWindowFocus: false,
  });

  if (error) {
    return (
      <Card className="mb-8">
        <div className="px-6 py-4 border-b border-gray-100 bg-gradient-to-r from-red-50 to-pink-50">
          <h3 className="text-lg font-semibold text-gray-800 flex items-center">
            <div className="w-1 h-6 bg-red-600 rounded-full mr-3"></div>
            Custos Fixos - Erro
          </h3>
        </div>
        <CardContent className="p-6">
          <div className="text-center text-red-500">
            Erro ao carregar custos fixos. Verifique a conexão com o banco de dados.
          </div>
        </CardContent>
      </Card>
    );
  }

  if (isLoading) {
    return (
      <Card className="mb-8">
        <div className="px-6 py-4 border-b border-gray-100 bg-gradient-to-r from-orange-50 to-amber-50">
          <h3 className="text-lg font-semibold text-gray-800 flex items-center">
            <div className="w-1 h-6 bg-orange-600 rounded-full mr-3"></div>
            Custos Fixos
          </h3>
        </div>
        <CardContent className="p-6">
          <div className="animate-pulse">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {[1, 2, 3].map(i => (
                <div key={i} className="h-20 bg-gray-200 rounded"></div>
              ))}
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (!custosFixos || custosFixos.length === 0) {
    return (
      <Card className="mb-8">
        <div className="px-6 py-4 border-b border-gray-100 bg-gradient-to-r from-orange-50 to-amber-50">
          <h3 className="text-lg font-semibold text-gray-800 flex items-center">
            <div className="w-1 h-6 bg-orange-600 rounded-full mr-3"></div>
            Custos Fixos
          </h3>
        </div>
        <CardContent className="p-6">
          <div className="text-center text-gray-500">
            Nenhum custo fixo encontrado
          </div>
        </CardContent>
      </Card>
    );
  }

  // Agrupar custos por tipo
  const custosPorTipo = custosFixos.reduce((acc, custo) => {
    if (!acc[custo.tipo]) {
      acc[custo.tipo] = [];
    }
    acc[custo.tipo].push(custo);
    return acc;
  }, {} as Record<string, CustoFixo[]>);

  // Calcular total
  const totalCustos = custosFixos.reduce((sum, custo) => sum + parseFloat(custo.valor), 0);

  return (
    <Card className="mb-8 shadow-sm border border-gray-200">
      <div className="px-6 py-4 border-b border-gray-100 bg-gradient-to-r from-orange-50 to-amber-50">
        <h3 className="text-lg font-semibold text-gray-800 flex items-center">
          <div className="w-1 h-6 bg-orange-600 rounded-full mr-3"></div>
          <Building className="text-orange-600 mr-2" size={18} />
          Custos Fixos
        </h3>
      </div>

      <CardContent className="p-6">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {Object.entries(custosPorTipo).map(([tipo, custos]) => (
            <div key={tipo} className="space-y-3">
              <h4 className="text-md font-semibold text-gray-700 flex items-center mb-3">
                {getTipoIcon(tipo)}
                {tipo}
              </h4>

              <div className="space-y-2">
                {custos.map((custo) => (
                  <div 
                    key={custo.id} 
                    className={`p-3 rounded-lg bg-white shadow-sm hover:shadow-md transition-shadow ${getTipoBorder(custo.tipo)}`}
                  >
                    <div className="text-sm font-medium text-gray-700 mb-1">
                      {custo.nome}
                    </div>
                    <div className="text-lg font-bold text-gray-900">
                      R$ {parseFloat(custo.valor).toLocaleString('pt-BR', { 
                        minimumFractionDigits: 2, 
                        maximumFractionDigits: 2 
                      })}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>

        {/* Total */}
        <div className="mt-8 pt-6 border-t border-gray-200">
          <div className="flex justify-between items-center">
            <span className="text-lg font-semibold text-gray-700">Total de Custos Fixos</span>
            <span className="text-2xl font-bold text-orange-600">
              R$ {totalCustos.toLocaleString('pt-BR', { 
                minimumFractionDigits: 2, 
                maximumFractionDigits: 2 
              })}
            </span>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}
